// Public Google Sheet (published as CSV) that powers the episode list live.
// Sheet: TVR_App_Database — tab "Journey"
const SHEET_ID = "1LQYCy84OWmOSnC4BHEFONB2Bw5vcCUz3c-3usU_ZXmQ";
const SHEET_CSV_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/gviz/tq?tqx=out:csv&sheet=Journey`;

// Minimal CSV parser that handles quoted fields (commas/quotes inside descriptions, etc.)
// Shared by both Pick the Route and Postcards' "song link" fields. People
// very often paste a link without the scheme (e.g. "youtube.com/watch?v=…"
// or "open.spotify.com/…" copied from a phone's share sheet). Two separate
// problems that causes if left as-is: the Apps Script side for Postcards
// requires an exact http(s):// prefix and silently DROPS anything else (the
// submission still succeeds, so nothing looks wrong — the link field just
// never reaches the Sheet); and even where the raw text IS saved as-is (the
// Route Submissions path), rendering it as <a href="www.example.com"> makes
// the browser treat it as a RELATIVE link on this site, not an external one
// — a click resolves to something like the-van-radio.vercel.app/www.example.com
// and 404s, instead of opening the song. Normalizing client-side, before
// sending, fixes both: the field reaches the server, and the link that gets
// saved actually works when clicked.
function normalizeMusicUrl(raw) {
  const trimmed = (raw || "").trim();
  if (!trimmed) return "";
  return /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
}

function parseCSV(text) {
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else inQuotes = false;
      } else field += c;
    } else {
      if (c === '"') inQuotes = true;
      else if (c === ",") { row.push(field); field = ""; }
      else if (c === "\n") { row.push(field); rows.push(row); row = []; field = ""; }
      else if (c === "\r") { /* skip */ }
      else field += c;
    }
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows.filter((r) => r.some((cell) => cell.trim() !== ""));
}

async function fetchJourneysFromSheet() {
  const res = await fetch(SHEET_CSV_URL);
  if (!res.ok) throw new Error(`Sheet fetch failed: ${res.status}`);
  const text = await res.text();
  const rows = parseCSV(text);
  const [header, ...body] = rows;
  const idx = {
    title: header.findIndex((h) => h.trim().toLowerCase() === "title"),
    date: header.findIndex((h) => h.trim().toLowerCase() === "date"),
    description: header.findIndex((h) => h.trim().toLowerCase() === "description"),
    audio: header.findIndex((h) => h.trim().toLowerCase() === "audio url"),
    image: header.findIndex((h) => h.trim().toLowerCase() === "image url"),
  };
  return body
    .map((r, i) => {
      const title = (r[idx.title] || "").trim();
      const match = title.match(/#(\d+)/);
      return {
        id: match ? parseInt(match[1], 10) : i + 1,
        title,
        date: (r[idx.date] || "").trim(),
        description: (r[idx.description] || "").trim(),
        audioUrl: (r[idx.audio] || "").trim(),
        imageUrl: (r[idx.image] || "").trim(),
      };
    })
    .filter((j) => j.title && j.audioUrl)
    .sort((a, b) => b.date.localeCompare(a.date));
}

// ---- Van Atlas data sources (brief section 7) ----
// Reuses the exact same public gviz CSV export mechanism already proven for
// Journeys — just pointed at the "Route Submissions" and "Postcards" tabs
// that the Apps Script webhook writes to. Route Submissions are shown
// unfiltered (this was always the plan for a future "community map" — see
// the original Pick the Route brief, section 11/12). Postcards are shown
// ONLY when their Status column is exactly "Approved" — enforced here, on
// the read side, so a Pending/Rejected postcard can never reach the public
// map no matter what.
const ROUTE_SUBMISSIONS_CSV_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent("Route Submissions")}`;
// SECURITY FIX: Postcards are no longer read via the public CSV export.
// That CSV exposes every row in the "Postcards" tab regardless of Status —
// so a Pending or Rejected postcard's story/photo reference would still be
// fetchable by anyone who found the URL, even though the UI itself never
// showed it. Postcards are now read through the Apps Script webhook's own
// "approved_postcards" action (see AppWebhookScript.gs.txt), which filters
// server-side and only ever returns rows whose Status is exactly "Approved"
// — a Pending/Rejected row never leaves the server at all. Route Submissions
// are unchanged (still the public CSV) — that was always meant to be an open
// community map, per the original Pick the Route brief.

async function fetchRouteSubmissionsForAtlas() {
  const res = await fetch(ROUTE_SUBMISSIONS_CSV_URL);
  if (!res.ok) throw new Error(`Route Submissions fetch failed: ${res.status}`);
  const rows = parseCSV(await res.text());
  if (!rows.length) return [];
  const [header, ...body] = rows;
  const col = (name) => header.findIndex((h) => h.trim().toLowerCase() === name);
  const idx = {
    id: col("submission id"), dest: col("destination"), lat: col("latitude"), lon: col("longitude"),
    genre: col("music genre"), song: col("song title"), artist: col("artist"), url: col("music url"), msg: col("user message"),
  };
  return body
    .map((r, i) => {
      const lat = parseFloat(r[idx.lat]);
      const lon = parseFloat(r[idx.lon]);
      return {
        kind: "route",
        id: r[idx.id] || `route-${i}`,
        placeName: (r[idx.dest] || "").trim(),
        locationText: (r[idx.dest] || "").trim(),
        lat: Number.isFinite(lat) ? lat : null,
        lon: Number.isFinite(lon) ? lon : null,
        genre: (r[idx.genre] || "").trim(),
        songTitle: (r[idx.song] || "").trim(),
        artist: (r[idx.artist] || "").trim(),
        musicUrl: (r[idx.url] || "").trim(),
        story: (r[idx.msg] || "").trim(),
        photoUrl: "",
      };
    })
    .filter((e) => e.placeName);
}

async function fetchApprovedPostcardsForAtlas() {
  if (!ROUTE_SHEET_WEBHOOK_URL || ROUTE_SHEET_WEBHOOK_URL.includes("PASTE_")) return [];
  const res = await fetch(`${ROUTE_SHEET_WEBHOOK_URL}?action=approved_postcards`);
  if (!res.ok) throw new Error(`Postcards fetch failed: ${res.status}`);
  const data = await res.json();
  if (!data || data.ok !== true || !Array.isArray(data.postcards)) throw new Error("Postcards response malformed");
  return data.postcards
    .map((p, i) => {
      const lat = parseFloat(p.latitude);
      const lon = parseFloat(p.longitude);
      return {
        kind: "postcard",
        id: p.id || `postcard-${i}`,
        placeName: String(p.placeName || "").trim(),
        locationText: String(p.locationText || "").trim(),
        lat: Number.isFinite(lat) ? lat : null,
        lon: Number.isFinite(lon) ? lon : null,
        story: String(p.story || "").trim(),
        displayName: String(p.displayName || "").trim(),
        songTitle: String(p.songTitle || "").trim(),
        artist: String(p.artist || "").trim(),
        musicUrl: String(p.musicUrl || "").trim(),
        photoUrl: String(p.photoUrl || "").trim(),
      };
    })
    .filter((e) => e.placeName);
}

async function fetchAtlasEntries() {
  const [routeEntries, postcardEntries] = await Promise.all([
    fetchRouteSubmissionsForAtlas().catch((err) => { console.error("Van Atlas: route submissions unavailable:", err); return []; }),
    fetchApprovedPostcardsForAtlas().catch((err) => { console.error("Van Atlas: postcards unavailable:", err); return []; }),
  ]);
  return [...routeEntries, ...postcardEntries];
}

// Groups entries that share (roughly) the same spot — rounding to 2 decimal
// degrees (~1km) — so the map doesn't get a separate pin for every single
// submission at the same destination. Entries with no real coordinates are
// never guessed onto the map — they're kept as a text-only list instead.
function buildAtlasGroups(entries) {
  const groups = new Map();
  const textOnly = [];
  // Never count the same submission twice (same source + same id), so the
  // numbers on the map are the real number of distinct entries.
  const seen = new Set();
  entries.forEach((e) => {
    const uid = `${e.kind}:${e.id}`;
    if (seen.has(uid)) return;
    seen.add(uid);
    if (e.lat == null || e.lon == null) {
      textOnly.push(e);
      return;
    }
    const key = `${e.lat.toFixed(2)},${e.lon.toFixed(2)}`;
    if (!groups.has(key)) groups.set(key, { lat: e.lat, lon: e.lon, name: e.placeName, entries: [] });
    const g = groups.get(key);
    if (e.kind === "route") g.name = e.placeName; // prefer the curated destination name for the pin label
    g.entries.push(e);
  });
  return { groups: Array.from(groups.values()), textOnly };
}

