// Swipeable/scrollable carousel of all Roadbook slides. Uses native CSS
// scroll-snap (not a custom drag implementation) so it works with normal
// touch swipe and trackpad scroll out of the box; the dot indicator and the
// prev/next arrows just call scrollTo on the same track, and onScroll (lightly
// debounced via rAF) keeps `active` in sync so the dots reflect manual swipes.
function RoadbookCarousel({ onNavigate, onPickChoice }) {
  const trackRef = useRef(null);
  const [active, setActive] = useState(0);
  const rafRef = useRef(null);

  const handleScroll = () => {
    if (rafRef.current) return;
    rafRef.current = requestAnimationFrame(() => {
      rafRef.current = null;
      const el = trackRef.current;
      if (!el) return;
      const slideW = el.clientWidth || 1;
      const idx = Math.round(el.scrollLeft / slideW);
      setActive(Math.max(0, Math.min(ROADBOOK_SECTIONS.length - 1, idx)));
    });
  };

  useEffect(() => () => { if (rafRef.current) cancelAnimationFrame(rafRef.current); }, []);

  const goTo = (idx) => {
    const el = trackRef.current;
    if (!el) return;
    const clamped = Math.max(0, Math.min(ROADBOOK_SECTIONS.length - 1, idx));
    el.scrollTo({ left: clamped * el.clientWidth, behavior: "smooth" });
  };

  return (
    <div className="roadbook-carousel">
      <div className="roadbook-track" ref={trackRef} onScroll={handleScroll}>
        {ROADBOOK_SECTIONS.map((s) => (
          <div className="roadbook-track-slide" key={s.n}>
            <RoadbookSlide section={s} onNavigate={onNavigate} onPickChoice={onPickChoice} />
          </div>
        ))}
      </div>

      {active > 0 && (
        <button type="button" className="roadbook-arrow roadbook-arrow-prev" onClick={() => goTo(active - 1)} aria-label="Προηγούμενο">
          <ChevronRight size={20} strokeWidth={2.4} style={{ transform: "rotate(180deg)" }} />
        </button>
      )}
      {active < ROADBOOK_SECTIONS.length - 1 && (
        <button type="button" className="roadbook-arrow roadbook-arrow-next" onClick={() => goTo(active + 1)} aria-label="Επόμενο">
          <ChevronRight size={20} strokeWidth={2.4} />
        </button>
      )}

      <div className="roadbook-dots">
        {ROADBOOK_SECTIONS.map((s, i) => (
          <button
            key={s.n}
            type="button"
            className={`roadbook-dot ${i === active ? "roadbook-dot-active" : ""}`}
            aria-label={`Slide ${s.n}`}
            onClick={() => goTo(i)}
          />
        ))}
      </div>
    </div>
  );
}

