// Fetches a real driving route (Athens → destination) from OpenRouteService.
// Returns an array of [lat, lon] points, or null if unavailable (e.g. an island
// with no road connection, or the API key isn't set yet / request failed) —
// callers should fall back to a straight indicative line in that case.
async function fetchRoadRoute(origin, dest, opts) {
  if (!ORS_API_KEY || ORS_API_KEY.includes("PASTE_")) return null;
  // Port coordinates are approximate — if a port point sits a bit further than
  // ORS's default snap distance from the nearest road, the first (unchanged,
  // default) request fails. Callers that deal with ports pass
  // { retryWideSnap: true } to get ONE extra attempt allowing a wider snap
  // radius. The default request always runs first, so routes that already
  // work behave exactly as before.
  async function request(radiuses) {
    const body = { coordinates: [[origin.lon, origin.lat], [dest.lon, dest.lat]] };
    if (radiuses) body.radiuses = radiuses;
    const res = await fetch("https://api.openrouteservice.org/v2/directions/driving-car/geojson", {
      method: "POST",
      headers: { Authorization: ORS_API_KEY, "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!res.ok) return null;
    const data = await res.json();
    const coords = data?.features?.[0]?.geometry?.coordinates;
    if (!coords || coords.length < 2) return null;
    return coords.map(([lon, lat]) => [lat, lon]);
  }
  try {
    const first = await request(null);
    if (first || !(opts && opts.retryWideSnap)) return first;
    return await request([3000, 3000]);
  } catch (err) {
    console.error("Road route unavailable, falling back to straight line:", err);
    return null;
  }
}

// Interpolates a [lat, lon] point at fraction t (0–1) along a multi-point path.
const ROUTE_VAN_ICON_WEBP = "data:image/webp;base64,";

function pointAlongPath(coords, t) {
  if (!coords || coords.length < 2) return coords ? coords[0] : null;
  const dists = [0];
  for (let i = 1; i < coords.length; i++) {
    const [lat1, lon1] = coords[i - 1];
    const [lat2, lon2] = coords[i];
    dists.push(dists[i - 1] + Math.hypot(lat2 - lat1, lon2 - lon1));
  }
  const target = t * dists[dists.length - 1];
  for (let i = 1; i < dists.length; i++) {
    if (dists[i] >= target) {
      const segT = dists[i] > dists[i - 1] ? (target - dists[i - 1]) / (dists[i] - dists[i - 1]) : 0;
      const [lat1, lon1] = coords[i - 1];
      const [lat2, lon2] = coords[i];
      return [lat1 + (lat2 - lat1) * segT, lon1 + (lon2 - lon1) * segT];
    }
  }
  return coords[coords.length - 1];
}

// The van/ferry icon is a real photo (3/4-angle, front pointing left), not a
// top-down vector — rotating a photographic side view to arbitrary angles
// would look broken (a van "lying down" when heading north/south). So
// instead of true rotation, we mirror it horizontally: unflipped = heading
// west, flipped = heading east. That's an honest approximation of "rotate
// according to direction of travel" given the asset we actually have — it
// keeps the van upright and grounded-looking rather than attempting a
// realism the source photo can't support.
function headingIsEastward(coords, t) {
  if (!coords || coords.length < 2) return true;
  const here = pointAlongPath(coords, t);
  const ahead = pointAlongPath(coords, Math.min(1, t + 0.02));
  if (!here || !ahead) return true;
  return ahead[1] >= here[1]; // comparing longitude
}
