function normalizePlaceName(s) {
  return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ς/g, "σ").trim();
}
function distanceKm(aLat, aLon, bLat, bLon) {
  const R = 6371;
  const dLat = ((bLat - aLat) * Math.PI) / 180;
  const dLon = ((bLon - aLon) * Math.PI) / 180;
  const x = Math.sin(dLat / 2) ** 2 + Math.cos((aLat * Math.PI) / 180) * Math.cos((bLat * Math.PI) / 180) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x));
}
// Recognises an island from ANY destination: by position first (so a point the
// person picks freely on the map still gets the ferry treatment), and by
// name only when the destination carries no usable coordinates. When circles
// of neighbouring islands overlap, the island whose centre is proportionally
// closest wins.
function findFerryIsland(destination) {
  if (!destination) return null;
  const hasCoords = Number.isFinite(destination.lat) && Number.isFinite(destination.lon);
  if (!hasCoords) {
    const key = normalizePlaceName(destination.name);
    return FERRY_ISLANDS.find((i) => normalizePlaceName(i.name) === key || (i.aliases || []).some((a) => normalizePlaceName(a) === key)) || null;
  }
  let best = null;
  let bestScore = Infinity;
  FERRY_ISLANDS.forEach((island) => {
    let score;
    if (island.bbox) {
      const [la0, lo0, la1, lo1] = island.bbox;
      if (destination.lat < la0 || destination.lat > la1 || destination.lon < lo0 || destination.lon > lo1) return;
      score = 0.5;
    } else {
      const d = distanceKm(destination.lat, destination.lon, island.center[0], island.center[1]);
      if (d > island.radiusKm) return;
      score = d / island.radiusKm;
    }
    if (score < bestScore) { best = island; bestScore = score; }
  });
  return best;
}
// Island journeys: any destination on a registered island gets
// { departurePort, arrivalPort } — arrival is the island port nearest to the
// chosen spot. A free-picked point with no island around it keeps the
// existing single-leg road behaviour (honest: we don't guess).
function getFerryInfo(destination) {
  const island = findFerryIsland(destination);
  if (!island) return null;
  const departurePort = FERRY_PORTS[island.departure] || PIRAEUS_PORT;
  let arrivalPort = island.ports[0];
  if (destination && Number.isFinite(destination.lat) && Number.isFinite(destination.lon) && island.ports.length > 1) {
    let bestD = Infinity;
    island.ports.forEach((p) => {
      const d = distanceKm(destination.lat, destination.lon, p.lat, p.lon);
      if (d < bestD) { bestD = d; arrivalPort = p; }
    });
  }
  // Ionian islands sail on the Ionian; everything else we model is Aegean.
  const seaName = arrivalPort.lon < 21.5 ? "το Ιόνιο" : "το Αιγαίο";
  return { islandName: island.name, departurePort, arrivalPort, seaName };
}
function isSamePlace(a, b) {
  return Math.abs(a.lat - b.lat) < 0.01 && Math.abs(a.lon - b.lon) < 0.01;
}

// Ferry marker: a real ferry picture (supplied by the project owner; 128px
// wide WebP, cut out from its background) with the branded van parked on its
// car deck, so the van stays visibly aboard during the sea leg. Mirrors as one
// rigid unit with headingIsEastward, same convention as the van icon
// (unflipped = bow pointing west). Sizes are set inline because the Leaflet
// stylesheet sets width:auto on marker-pane images and would override a class.
const ROUTE_FERRY_ICON_WEBP = "data:image/webp;base64,";
function makeFerryIcon(facingEast) {
  return L.divIcon({
    className: "route-leaflet-van-wrap",
    html: `<div class="route-leaflet-ferry${facingEast ? " route-leaflet-ferry-flip" : ""}"><img src="${ROUTE_FERRY_ICON_WEBP}" alt="" style="width:64px;height:auto;display:block" /><img src="${ROUTE_VAN_ICON_WEBP}" alt="" style="width:20px;height:auto" class="route-leaflet-ferry-van" /></div>`,
    iconSize: [1, 1],
    iconAnchor: [0, 0],
  });
}

// Builds the ordered list of legs for an island journey: road → ferry →
// (optional) road. `secondLegNeeded` is false when the chosen spot IS the
// arrival port, so there's nothing left to drive after disembarking.
function buildFerryLegs(destination, ferryInfo, routeCoords, routeCoords2, secondLegNeeded) {
  const legs = [];
  const leg1Ready = !!(routeCoords && routeCoords.length > 1);
  const leg1 = leg1Ready ? routeCoords : [[ATHENS.lat, ATHENS.lon], [ferryInfo.departurePort.lat, ferryInfo.departurePort.lon]];
  legs.push({ kind: "road", coords: leg1, ready: leg1Ready, label: ferryInfo.departurePort.name });
  legs.push({
    kind: "ferry",
    coords: [[ferryInfo.departurePort.lat, ferryInfo.departurePort.lon], [ferryInfo.arrivalPort.lat, ferryInfo.arrivalPort.lon]],
    ready: true,
    label: ferryInfo.arrivalPort.name,
  });
  if (secondLegNeeded) {
    const leg2Ready = !!(routeCoords2 && routeCoords2.length > 1);
    const leg2 = leg2Ready ? routeCoords2 : [[ferryInfo.arrivalPort.lat, ferryInfo.arrivalPort.lon], [destination.lat, destination.lon]];
    legs.push({ kind: "road", coords: leg2, ready: leg2Ready, label: destination.name });
  }
  return legs;
}

// Multi-leg map for island journeys: renders every leg (road legs solid/
// dashed depending on whether the real route loaded, the sea crossing always
// dashed) and animates a van or ferry icon along whichever leg is active.
function RouteLeafletFerryMap({ legs, activeLegIndex, vanPct, badge }) {
  const allCoords = legs.flatMap((l) => l.coords);
  const activeLeg = legs[activeLegIndex];
  const vanPos = activeLeg && vanPct != null ? pointAlongPath(activeLeg.coords, vanPct) : null;
  const vanFacingEast = activeLeg && vanPct != null ? headingIsEastward(activeLeg.coords, vanPct) : true;
  return (
    <div className="route-leaflet-wrap">
      <MapContainer
        center={[38.6, 23.4]}
        zoom={6}
        scrollWheelZoom={false}
        dragging={false}
        doubleClickZoom={false}
        zoomControl={false}
        touchZoom={false}
        className="route-leaflet-map"
      >
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <FitRouteBounds coords={allCoords} />
        {legs.map((leg, i) => (
          <Polyline
            key={i}
            positions={leg.coords}
            pathOptions={
              leg.kind === "ferry"
                ? { color: "#FFB020", weight: 3, dashArray: "2,10", opacity: 0.9 }
                : leg.ready
                  ? { color: "#39ACD0", weight: 4, opacity: 0.9 }
                  : { color: "#39ACD0", weight: 3, dashArray: "1,10", opacity: 0.85 }
            }
          />
        ))}
        <Marker position={legs[0].coords[0]} icon={makeRoutePinIcon("ΑΘΗΝΑ", false)} />
        {legs.map((leg, i) => (
          <Marker
            key={"pin" + i}
            position={leg.coords[leg.coords.length - 1]}
            icon={makeRoutePinIcon(leg.label, i === legs.length - 1)}
          />
        ))}
        {vanPos && <Marker position={vanPos} icon={activeLeg.kind === "ferry" ? makeFerryIcon(vanFacingEast) : makeVanIcon(vanFacingEast)} />}
      </MapContainer>
      {badge && <div className="route-map-badge">{badge}</div>}
    </div>
  );
}

function invertProjection(leftPct, topPct) {
  const lon = GREECE_BOUNDS.lonMin + (leftPct / 100) * (GREECE_BOUNDS.lonMax - GREECE_BOUNDS.lonMin);
  const lat = GREECE_BOUNDS.latMax - (topPct / 100) * (GREECE_BOUNDS.latMax - GREECE_BOUNDS.latMin);
  return { lat, lon };
}

async function reverseGeocodePlace(lat, lon) {
  try {
    const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lon}&accept-language=el&zoom=12`);
    if (!res.ok) return null;
    const data = await res.json();
    const a = data.address || {};
    return a.village || a.town || a.city || a.municipality || a.county || a.state || data.display_name || null;
  } catch (e) {
    return null;
  }
}

function RouteMapBoard({ selected, onSelect, onFreePick, mode, vanPct }) {
  const dest = selected ? projectLatLon(selected.lat, selected.lon) : null;
  const origin = projectLatLon(ATHENS.lat, ATHENS.lon);
  const vanPos = dest && mode === "driving"
    ? { left: origin.left + (dest.left - origin.left) * vanPct, top: origin.top + (dest.top - origin.top) * vanPct }
    : null;

  function handleBoardClick(e) {
    if (mode !== "pick" || !onFreePick) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const leftPct = ((e.clientX - rect.left) / rect.width) * 100;
    const topPct = ((e.clientY - rect.top) / rect.height) * 100;
    const { lat, lon } = invertProjection(leftPct, topPct);
    onFreePick(lat, lon);
  }

  return (
    <div className={`route-board ${mode === "pick" ? "route-board-clickable" : ""}`} onClick={handleBoardClick}>
      <div className="route-board-dots" />
      {(mode === "driving" || mode === "preview") && dest && (
        <svg className="route-board-line" viewBox="0 0 100 100" preserveAspectRatio="none">
          <line x1={origin.left} y1={origin.top} x2={dest.left} y2={dest.top} strokeDasharray="2.2,2.2" />
        </svg>
      )}
      <div className="route-pin route-pin-origin" style={{ left: `${origin.left}%`, top: `${origin.top}%` }}>
        <span className="route-pin-dot" />
        <span className="route-pin-label">ΑΘΗΝΑ</span>
      </div>
      {mode === "pick" && ROUTE_DESTINATIONS.map((d) => {
        const pos = projectLatLon(d.lat, d.lon);
        const isSel = selected && selected.name === d.name;
        return (
          <button
            key={d.name}
            className={`route-pin route-pin-choice ${isSel ? "route-pin-active" : ""}`}
            style={{ left: `${pos.left}%`, top: `${pos.top}%` }}
            onClick={(e) => { e.stopPropagation(); onSelect(d); }}
          >
            <MapPin size={16} strokeWidth={2.3} />
            <span className="route-pin-label">{d.name}</span>
          </button>
        );
      })}
      {mode === "pick" && selected && dest && !ROUTE_DESTINATIONS.some((d) => d.name === selected.name) && (
        <div className="route-pin route-pin-active route-pin-custom" style={{ left: `${dest.left}%`, top: `${dest.top}%` }}>
          <MapPin size={16} strokeWidth={2.3} />
          <span className="route-pin-label">{selected.resolving ? "…" : selected.name}</span>
        </div>
      )}
      {mode !== "pick" && dest && (
        <div className="route-pin route-pin-dest route-pin-active" style={{ left: `${dest.left}%`, top: `${dest.top}%` }}>
          <MapPin size={16} strokeWidth={2.3} />
          <span className="route-pin-label">{selected.name}</span>
        </div>
      )}
      {vanPos && (
        <div className="route-van" style={{ left: `${vanPos.left}%`, top: `${vanPos.top}%` }}>🚐</div>
      )}
    </div>
  );
}

function RouteStepper({ step }) {
  const idx = ROUTE_STEP_INDEX[step];
  if (idx === undefined) return null;
  return (
    <div className="route-stepper">
      {ROUTE_STEP_LABELS.map((label, i) => (
        <React.Fragment key={label}>
          <span className={`route-step ${i === idx ? "route-step-active" : i < idx ? "route-step-done" : ""}`}>
            {String(i + 1).padStart(2, "0")} {label}
          </span>
          {i < ROUTE_STEP_LABELS.length - 1 && <span className="route-step-arrow">→</span>}
        </React.Fragment>
      ))}
    </div>
  );
}

// Stages where the van (or ferry) icon animates along a leg, and what
// follows once the animation finishes. Continental destinations only ever
// use "driving". Island destinations run driving_to_port → (message:
// boarding_ferry) → ferry_crossing → (message: disembarking, dynamic next)
// → driving_to_destination (only if the chosen spot isn't the port itself).
const ROUTE_ANIM_DURATIONS = {
  driving: 2600,
  driving_to_port: 1800,
  ferry_crossing: 2200,
  driving_to_destination: 1800,
};
const ROUTE_ANIM_NEXT = {
  driving: "arrived",
  driving_to_port: "boarding_ferry",
  ferry_crossing: "disembarking",
  driving_to_destination: "arrived",
};
// Message-only stages (no icon movement) and how long they hold before
// advancing. "disembarking" is handled separately since its next step
// depends on whether a second road leg is needed.
const ROUTE_MESSAGE_DURATIONS = { preparing: 900, boarding_ferry: 1600 };
const ROUTE_MESSAGE_NEXT = { preparing: "driving_to_port", boarding_ferry: "ferry_crossing" };

function prefersReducedMotion() {
  try { return !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches); } catch (e) { return false; }
}

function PickRouteView() {
  const [step, setStep] = useState("intro");
  const [destination, setDestination] = useState(null);
  const [genre, setGenre] = useState(null);
  const [songTitle, setSongTitle] = useState("");
  const [artist, setArtist] = useState("");
  const [musicUrl, setMusicUrl] = useState("");
  const [story, setStory] = useState("");
  const [vanPct, setVanPct] = useState(0);
  const [blockedMsg, setBlockedMsg] = useState("");
  const [routeCoords, setRouteCoords] = useState(null);
  const [routeStatus, setRouteStatus] = useState("idle"); // idle | loading | ready | unavailable
  // Second leg (arrival port → destination) — only used for island journeys.
  const [routeCoords2, setRouteCoords2] = useState(null);
  const [routeStatus2, setRouteStatus2] = useState("idle");
  const rafRef = useRef(null);

  const ferryInfo = getFerryInfo(destination);
  const secondLegNeeded = !!ferryInfo && !isSamePlace(ferryInfo.arrivalPort, destination || ferryInfo.arrivalPort);
  const ferryLegs = ferryInfo ? buildFerryLegs(destination, ferryInfo, routeCoords, routeCoords2, secondLegNeeded) : null;

  // Animated stages (van/ferry icon moving along the active leg).
  useEffect(() => {
    const duration = ROUTE_ANIM_DURATIONS[step];
    if (!duration) return;
    // Reduced-motion: no continuous gliding — show the end of the leg, hold
    // briefly, then move on to the next stage.
    if (prefersReducedMotion()) {
      setVanPct(1);
      const t = setTimeout(() => {
        setVanPct(0);
        setStep(ROUTE_ANIM_NEXT[step]);
      }, 700);
      return () => clearTimeout(t);
    }
    const start = performance.now();
    function tick(now) {
      const t = Math.min(1, (now - start) / duration);
      setVanPct(t);
      if (t < 1) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        setTimeout(() => {
          setVanPct(0);
          setStep(ROUTE_ANIM_NEXT[step]);
        }, 350);
      }
    }
    rafRef.current = requestAnimationFrame(tick);
    return () => rafRef.current && cancelAnimationFrame(rafRef.current);
  }, [step]);

  // Message-only stages ("preparing" / "boarding_ferry") — just a hold, then advance.
  useEffect(() => {
    const duration = ROUTE_MESSAGE_DURATIONS[step];
    if (!duration) return;
    const t = setTimeout(() => setStep(ROUTE_MESSAGE_NEXT[step]), duration);
    return () => clearTimeout(t);
  }, [step]);

  // "disembarking" is a message stage too, but its next step depends on
  // whether there's a second road leg to drive (chosen spot vs. the port itself).
  useEffect(() => {
    if (step !== "disembarking") return;
    const t = setTimeout(() => setStep(secondLegNeeded ? "driving_to_destination" : "arrived"), 900);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step]);

  function submitRoute() {
    const payload = {
      destination_name: destination.name,
      latitude: destination.lat,
      longitude: destination.lon,
      music_genre: genre,
      song_title: songTitle.trim(),
      artist: artist.trim(),
      music_url: normalizeMusicUrl(musicUrl) || null,
      user_message: story.trim() || null,
      source: "web",
      status: "new",
    };
    // Primary: append a row to the "Route Submissions" tab via Google Apps Script webhook.
    if (ROUTE_SHEET_WEBHOOK_URL && !ROUTE_SHEET_WEBHOOK_URL.includes("PASTE_")) {
      fetch(ROUTE_SHEET_WEBHOOK_URL, {
        method: "POST",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify(payload),
      })
        .then((res) => res.text().then((body) => console.log("Route submission (Sheet) response:", res.status, body)))
        .catch((err) => console.error("Route submission (Sheet) could not be saved:", err));
    }
    // Backup: also keep a copy in Firestore in case the Sheet webhook isn't set up yet.
    (async () => {
      try {
        const fb = await loadFirebase();
        await fb.addDoc(fb.collection(fb.db, "route-submissions"), {
          ...payload,
          created_at: fb.serverTimestamp(),
        });
      } catch (err) {
        console.error("Route submission (backup) could not be saved:", err);
      }
    })();
  }

  function handleFreePick(lat, lon) {
    const placeholder = { name: `Σημείο (${lat.toFixed(2)}, ${lon.toFixed(2)})`, lat, lon, resolving: true };
    setDestination(placeholder);
    reverseGeocodePlace(lat, lon).then((name) => {
      setDestination((d) => {
        if (!d || d.lat !== lat || d.lon !== lon) return d;
        return { ...d, name: name || d.name, resolving: false };
      });
    });
  }

  function reset() {
    setStep("intro");
    setDestination(null);
    setGenre(null);
    setSongTitle("");
    setArtist("");
    setMusicUrl("");
    setStory("");
    setVanPct(0);
    setBlockedMsg("");
    setRouteCoords(null);
    setRouteStatus("idle");
    setRouteCoords2(null);
    setRouteStatus2("idle");
  }

  // Pre-fetch the real road route(s) as soon as a destination is picked, so
  // they're likely ready by the time the person reaches the preview step —
  // no surprise wait on launch. Islands need two road legs (Athens → port,
  // and arrival port → the chosen spot) bridged by an indicative sea crossing.
  useEffect(() => {
    if (!destination || destination.resolving) return;
    let cancelled = false;
    const ferry = getFerryInfo(destination);
    setRouteStatus("loading");
    setRouteCoords(null);
    setRouteStatus2("idle");
    setRouteCoords2(null);
    if (ferry) {
      fetchRoadRoute(ATHENS, ferry.departurePort, { retryWideSnap: true }).then((coords) => {
        if (cancelled) return;
        setRouteCoords(coords);
        setRouteStatus(coords ? "ready" : "unavailable");
      });
      if (!isSamePlace(ferry.arrivalPort, destination)) {
        setRouteStatus2("loading");
        fetchRoadRoute(ferry.arrivalPort, destination, { retryWideSnap: true }).then((coords) => {
          if (cancelled) return;
          setRouteCoords2(coords);
          setRouteStatus2(coords ? "ready" : "unavailable");
        });
      }
    } else {
      fetchRoadRoute(ATHENS, destination).then((coords) => {
        if (cancelled) return;
        setRouteCoords(coords);
        setRouteStatus(coords ? "ready" : "unavailable");
      });
    }
    return () => { cancelled = true; };
  }, [destination]);

  function launch() {
    if (!canSubmitRoute()) {
      setBlockedMsg("Το Van μόλις γύρισε από μια διαδρομή — δώσε του κάνα-δυο λεπτά ανάσα και δοκίμασε ξανά. 🚐");
      return;
    }
    setBlockedMsg("");
    markRouteSubmitted();
    submitRoute();
    setVanPct(0);
    setStep(ferryInfo ? "preparing" : "driving");
  }

  const canProceedSong = destination && genre && songTitle.trim() && artist.trim();

  return (
    <div className="view">
      {step === "intro" && (
        <div className="route-intro fade-in">
          <div className="eyebrow">PICK THE ROUTE 🚐</div>
          <h1 className="page-title">Εσύ αποφασίζεις τη διαδρομή.</h1>
          <p className="route-intro-text">
            Διάλεξε έναν προορισμό, ένα μουσικό ύφος και το τραγούδι που θέλεις να πάρουμε μαζί μας. Το Van είναι έτοιμο.
          </p>
          <button className="pill-btn" onClick={() => setStep("destination")}>Ξεκίνα τη διαδρομή</button>
        </div>
      )}

      {step === "destination" && (
        <div className="fade-in">
          <RouteStepper step={step} />
          <div className="route-step-heading">📍 ΠΟΥ ΠΑΜΕ;</div>
          <p className="route-intro-text">Κάνε zoom, μετακίνησε τον χάρτη και πάτα οπουδήποτε — ή διάλεξε έναν δημοφιλή προορισμό.</p>
          <RouteLeafletMap selected={destination} onSelect={setDestination} onFreePick={handleFreePick} />
          {destination && (
            <div className="route-confirm-line">
              📍 {destination.resolving ? "Εντοπίζουμε το σημείο..." : destination.name}
              <br /><span>Η στάση σου προστέθηκε στη διαδρομή.</span>
              {getFerryInfo(destination) && <><br /><span>⛴️ Αυτός ο προορισμός έχει και κομμάτι με πλοίο.</span></>}
            </div>
          )}
          <div className="route-nav">
            <button className="pill-btn" disabled={!destination} onClick={() => setStep("genre")}>Συνέχεια</button>
          </div>
        </div>
      )}

      {step === "genre" && (
        <div className="fade-in">
          <RouteStepper step={step} />
          <div className="route-step-heading">🎵 ΤΙ ΑΚΟΥΜΕ ΣΤΟΝ ΔΡΟΜΟ;</div>
          <div className="route-genre-grid">
            {ROUTE_GENRES.map((g) => (
              <button
                key={g}
                className={`route-genre-card ${genre === g ? "route-genre-active" : ""}`}
                onClick={() => setGenre(g)}
              >
                {g}
              </button>
            ))}
          </div>
          <div className="route-nav">
            <button className="pill-btn pill-btn-ghost" onClick={() => setStep("destination")}>Πίσω</button>
            <button className="pill-btn" disabled={!genre} onClick={() => setStep("song")}>Συνέχεια</button>
          </div>
        </div>
      )}

      {step === "song" && (
        <div className="fade-in">
          <RouteStepper step={step} />
          <div className="route-step-heading">🎧 ΤΙ ΠΑΙΡΝΟΥΜΕ ΜΑΖΙ ΜΑΣ;</div>
          <p className="route-intro-text">Ποιο τραγούδι πρέπει να ακούσουμε όταν φτάσουμε εκεί;</p>
          <input className="route-input" placeholder="Π.χ. Τίτλος τραγουδιού" value={songTitle} onChange={(e) => setSongTitle(e.target.value)} maxLength={80} />
          <input className="route-input" placeholder="Π.χ. Καλλιτέχνης" value={artist} onChange={(e) => setArtist(e.target.value)} maxLength={80} />
          <input className="route-input" placeholder="Βάλε το link του τραγουδιού (προαιρετικό)" value={musicUrl} onChange={(e) => setMusicUrl(e.target.value)} maxLength={300} />
          <div className="route-step-heading route-step-heading-sm">💬 ΓΙΑΤΙ ΑΥΤΟ ΤΟ ΤΡΑΓΟΥΔΙ;</div>
          <textarea className="route-textarea" placeholder="Μια μικρή ιστορία, μια ανάμνηση ή ένας λόγος που το διάλεξες..." value={story} onChange={(e) => setStory(e.target.value)} maxLength={500} />
          <div className="route-nav">
            <button className="pill-btn pill-btn-ghost" onClick={() => setStep("genre")}>Πίσω</button>
            <button className="pill-btn" disabled={!canProceedSong} onClick={() => setStep("preview")}>Συνέχεια</button>
          </div>
        </div>
      )}

      {step === "preview" && (
        <div className="fade-in">
          <RouteStepper step={step} />
          <div className="route-step-heading">Η ΔΙΑΔΡΟΜΗ ΣΟΥ</div>
          {ferryInfo ? (
            <>
              <RouteLeafletFerryMap
                legs={ferryLegs}
                activeLegIndex={0}
                vanPct={null}
                badge={`Αθήνα → ${ferryInfo.departurePort.name} (οδικώς) → ${ferryInfo.arrivalPort.name} (πλοίο) → ${destination.name}`}
              />
              <p className="route-ferry-note">⛴️ Το κομμάτι με το πλοίο είναι ενδεικτικό — δεν δείχνει πραγματικό δρομολόγιο ή ζωντανή θέση πλοίου.</p>
            </>
          ) : (
            <RouteLeafletJourneyMap destination={destination} mode="preview" vanPct={0} routeCoords={routeCoords} routeStatus={routeStatus} />
          )}
          <div className="route-preview-card">
            <div>📍 Προορισμός: <strong>{destination.name}</strong></div>
            <div>🎵 Ύφος: <strong>{genre}</strong></div>
            <div>🎧 Soundtrack: <strong>{songTitle} — {artist}</strong></div>
          </div>
          {blockedMsg && <div className="route-blocked-msg">{blockedMsg}</div>}
          <div className="route-nav route-nav-center">
            <button className="pill-btn pill-btn-ghost" onClick={() => setStep("song")}>Πίσω</button>
            <button className="pill-btn route-launch-btn" onClick={launch}>ΒΑΛΕ ΜΠΡΟΣ 🚐</button>
          </div>
          <p className="route-intro-text route-intro-text-center">Η διαδρομή ξεκινάει.</p>
        </div>
      )}

      {step === "driving" && (
        <div className="fade-in route-driving">
          <div className="route-step-heading route-step-heading-center">Η διαδρομή ξεκινάει...</div>
          <RouteLeafletJourneyMap destination={destination} mode="driving" vanPct={vanPct} routeCoords={routeCoords} />
        </div>
      )}

      {step === "preparing" && (
        <div className="fade-in route-driving">
          <div className="route-ferry-message">Ετοιμάζουμε τη διαδρομή… 🚐</div>
        </div>
      )}

      {step === "driving_to_port" && ferryInfo && (
        <div className="fade-in route-driving">
          <div className="route-step-heading route-step-heading-center">Προς το λιμάνι, {ferryInfo.departurePort.name}...</div>
          <RouteLeafletFerryMap legs={ferryLegs} activeLegIndex={0} vanPct={vanPct} />
        </div>
      )}

      {step === "boarding_ferry" && (
        <div className="fade-in route-driving">
          <div className="route-ferry-message">Λύνουμε κάβους… ⛴️</div>
        </div>
      )}

      {step === "ferry_crossing" && ferryInfo && (
        <div className="fade-in route-driving">
          <div className="route-step-heading route-step-heading-center">Διασχίζουμε {ferryInfo.seaName}… ⛴️</div>
          <RouteLeafletFerryMap
            legs={ferryLegs}
            activeLegIndex={1}
            vanPct={vanPct}
            badge="Ενδεικτική διαδρομή — όχι πραγματικό δρομολόγιο ή ζωντανή θέση πλοίου"
          />
        </div>
      )}

      {step === "disembarking" && (
        <div className="fade-in route-driving">
          <div className="route-ferry-message">Αράξαμε στο λιμάνι… 🚢</div>
        </div>
      )}

      {step === "driving_to_destination" && ferryInfo && (
        <div className="fade-in route-driving">
          <div className="route-step-heading route-step-heading-center">Τελευταίο κομμάτι μέχρι το {destination.name}...</div>
          <RouteLeafletFerryMap legs={ferryLegs} activeLegIndex={2} vanPct={vanPct} />
        </div>
      )}

      {step === "arrived" && (
        <div className="fade-in route-arrived">
          <div className="route-step-heading route-step-heading-center">ΕΦΤΑΣΕΣ. 📍</div>
          <div className="route-arrived-dest">{destination.name}</div>
          <div className="route-arrived-song">🎵 Το soundtrack σου:<br /><strong>{artist} — {songTitle}</strong></div>
          <div className="route-arrived-note">Η ΔΙΑΔΡΟΜΗ ΣΟΥ ΜΠΗΚΕ ΣΤΗ ΛΙΣΤΑ ΜΑΣ.</div>
          <p className="route-intro-text route-intro-text-center">Ίσως μια μέρα το Van να περάσει πραγματικά από εδώ.</p>
          <div className="route-nav route-nav-center">
            <button className="pill-btn" onClick={reset}>Διάλεξε άλλη διαδρομή</button>
          </div>
        </div>
      )}
    </div>
  );
}

// ---- POSTCARDS FROM THE ROAD 💌 (brief section 6) ----
// Real photo upload (not just a local preview) travels through the SAME
// Apps Script webhook already used for Route Submissions (see
// AppWebhookScript.gs.txt), routed by form_type:"postcard". The script saves
// the photo to a dedicated Google Drive folder and appends a row to a new
// "Postcards" Sheet tab with status "Pending" — moderation happens by hand,
// by editing that Status cell to "Approved"/"Rejected" directly in the Sheet
// (documented at the bottom of the script file). Only "Approved" rows will
// ever be read back into the app (Van Atlas, Phase 5) — nothing submitted
// here is shown publicly right away. The photo itself also stays PRIVATE in
// Drive until approved (see onPostcardStatusEdit in the script) — it isn't
// enough for the UI to just not show it; the file itself isn't public yet.
const POSTCARD_MAX_FILE_BYTES = 10 * 1024 * 1024; // reject over 10MB before even trying to resize
const POSTCARD_MAX_DIM = 1600; // resized longest side, px
const POSTCARD_JPEG_QUALITY = 0.82;
// Client-side cooldown — a convenience against accidental double-submits,
// not real spam protection. The server has its own rate limit (see the
// script) because this check alone can always be bypassed.
const POSTCARD_COOLDOWN_MS = 5 * 60 * 1000;
function canSubmitPostcard() {
  try {
    const last = window.localStorage.getItem("tvr_postcard_last");
    if (last && Date.now() - Number(last) < POSTCARD_COOLDOWN_MS) return false;
  } catch (e) { /* storage unavailable — allow submission */ }
  return true;
}
function markPostcardSubmitted() {
  try { window.localStorage.setItem("tvr_postcard_last", String(Date.now())); } catch (e) { /* ignore */ }
}
// Maps the server's error codes (AppWebhookScript.gs.txt) to friendly Greek
// messages — never a raw error code shown to the person.
const POSTCARD_ERROR_MESSAGES = {
  "consent-required": "Χρειάζεται να επιλέξεις τη συγκατάθεση δημοσίευσης για να στείλεις την καρτ ποστάλ.",
  "missing-fields": "Λείπει κάποιο υποχρεωτικό πεδίο — έλεγξε τη φόρμα και δοκίμασε ξανά.",
  "photo-required": "Χρειάζεται μια φωτογραφία για να σταλεί η καρτ ποστάλ.",
  "invalid-photo-type": "Αυτός ο τύπος αρχείου δεν υποστηρίζεται — δοκίμασε jpg, png, webp ή gif.",
  "photo-too-large": "Η φωτογραφία είναι πολύ μεγάλη — δοκίμασε μικρότερη.",
  "photo-upload-failed": "Η φωτογραφία δεν αποθηκεύτηκε — δοκίμασε ξανά σε λίγο.",
  "rate-limited": "Πολλές υποβολές αυτή τη στιγμή — δοκίμασε ξανά σε λίγα λεπτά.",
  "invalid-request": "Κάτι δεν πήγε καλά με την υποβολή — δοκίμασε ξανά.",
  "webhook-not-configured": "Η αποθήκευση δεν έχει ρυθμιστεί ακόμα — δοκίμασε ξανά σε λίγο.",
};
function postcardErrorMessage(code) {
  return POSTCARD_ERROR_MESSAGES[code] || "Κάτι δεν πήγε καλά και η καρτ ποστάλ δεν στάλθηκε. Τα στοιχεία σου παραμένουν εδώ — δοκίμασε ξανά.";
}

function validatePostcardPhoto(file) {
  if (!file) return "Διάλεξε μια φωτογραφία.";
  if (!file.type || !file.type.startsWith("image/")) return "Το αρχείο πρέπει να είναι φωτογραφία (jpg, png κ.λπ.).";
  if (file.size > POSTCARD_MAX_FILE_BYTES) return "Η φωτογραφία είναι πολύ μεγάλη (μέγιστο 10MB).";
  return null;
}

// Resizes + compresses the photo in the browser before upload, so even a
// large phone photo becomes a small JPEG — faster to send, and a safe
// payload size for the Apps Script webhook.
function resizePostcardPhoto(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("read-failed"));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("decode-failed"));
      img.onload = () => {
        let { width, height } = img;
        if (width > height && width > POSTCARD_MAX_DIM) {
          height = Math.round((height * POSTCARD_MAX_DIM) / width);
          width = POSTCARD_MAX_DIM;
        } else if (height >= width && height > POSTCARD_MAX_DIM) {
          width = Math.round((width * POSTCARD_MAX_DIM) / height);
          height = POSTCARD_MAX_DIM;
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        canvas.getContext("2d").drawImage(img, 0, 0, width, height);
        const dataUrl = canvas.toDataURL("image/jpeg", POSTCARD_JPEG_QUALITY);
        resolve({ base64: dataUrl.split(",")[1], mime: "image/jpeg" });
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

function PostcardsView() {
  const [placeName, setPlaceName] = useState("");
  const [locationText, setLocationText] = useState("");
  const [pickedPoint, setPickedPoint] = useState(null); // optional real coords — never invented
  const [showMap, setShowMap] = useState(false);
  const [story, setStory] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [songTitle, setSongTitle] = useState("");
  const [artist, setArtist] = useState("");
  const [musicUrl, setMusicUrl] = useState("");
  const [consent, setConsent] = useState(false);
  const [photoFile, setPhotoFile] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [photoError, setPhotoError] = useState("");
  const [status, setStatus] = useState("form"); // form | submitting | success | error
  const [errorMsg, setErrorMsg] = useState("");
  const [blockedMsg, setBlockedMsg] = useState("");
  const fileInputRef = useRef(null);

  function handlePhotoChange(e) {
    const file = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!file) return;
    const err = validatePostcardPhoto(file);
    if (err) {
      setPhotoError(err);
      return;
    }
    setPhotoError("");
    setPhotoFile(file);
    const reader = new FileReader();
    reader.onload = () => setPhotoPreview(reader.result);
    reader.readAsDataURL(file);
  }

  function removePhoto() {
    setPhotoFile(null);
    setPhotoPreview(null);
    setPhotoError("");
  }

  function handleFreePick(lat, lon) {
    const placeholder = { lat, lon, name: `Σημείο (${lat.toFixed(2)}, ${lon.toFixed(2)})`, resolving: true };
    setPickedPoint(placeholder);
    reverseGeocodePlace(lat, lon).then((name) => {
      setPickedPoint((p) => (p && p.lat === lat && p.lon === lon ? { ...p, name: name || p.name, resolving: false } : p));
    });
  }

  const canSubmit = placeName.trim() && locationText.trim() && story.trim() && photoFile && consent && !photoError;

  async function handleSubmit() {
    if (!canSubmit) return;
    if (!canSubmitPostcard()) {
      setBlockedMsg("Μόλις έστειλες μια καρτ ποστάλ — δώσε κάνα-δυο λεπτά και δοκίμασε ξανά. 💌");
      return;
    }
    setBlockedMsg("");
    setStatus("submitting");
    setErrorMsg("");
    try {
      const { base64, mime } = await resizePostcardPhoto(photoFile);
      const payload = {
        form_type: "postcard",
        place_name: placeName.trim(),
        location_text: locationText.trim(),
        latitude: pickedPoint ? pickedPoint.lat : "",
        longitude: pickedPoint ? pickedPoint.lon : "",
        story: story.trim(),
        display_name: displayName.trim() || null,
        song_title: songTitle.trim() || null,
        artist: artist.trim() || null,
        music_url: normalizeMusicUrl(musicUrl) || null,
        photo_base64: base64,
        photo_mime: mime,
        // FIX: this was being checked client-side (canSubmit requires it)
        // but never actually sent, so the Sheet never recorded whether the
        // person had agreed to publication. Now sent explicitly, and the
        // server rejects the submission outright if it isn't exactly `true`.
        consent: consent === true,
      };
      if (!ROUTE_SHEET_WEBHOOK_URL || ROUTE_SHEET_WEBHOOK_URL.includes("PASTE_")) {
        throw new Error("webhook-not-configured");
      }
      const res = await fetch(ROUTE_SHEET_WEBHOOK_URL, {
        method: "POST",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify(payload),
      });
      const text = await res.text();
      let parsed = null;
      try { parsed = JSON.parse(text); } catch (e) { /* non-JSON response */ }
      if (!res.ok || !parsed) throw new Error("invalid-request");
      if (!parsed.ok) throw new Error(parsed.error || "invalid-request");
      markPostcardSubmitted();
      // Lightweight metadata-only backup (no photo — Firestore isn't the
      // real photo store here, Drive is) in case the Sheet write needs
      // double-checking later.
      (async () => {
        try {
          const fb = await loadFirebase();
          await fb.addDoc(fb.collection(fb.db, "postcard-submissions"), {
            place_name: payload.place_name,
            location_text: payload.location_text,
            latitude: payload.latitude,
            longitude: payload.longitude,
            story: payload.story,
            display_name: payload.display_name,
            song_title: payload.song_title,
            artist: payload.artist,
            music_url: payload.music_url,
            consent: payload.consent,
            photo_saved: !!parsed.photo_saved,
            status: "Pending",
            created_at: fb.serverTimestamp(),
          });
        } catch (err) {
          console.error("Postcard backup (metadata only) could not be saved:", err);
        }
      })();
      setStatus("success");
    } catch (err) {
      console.error("Postcard submission failed:", err);
      setStatus("error");
      setErrorMsg(postcardErrorMessage(err && err.message));
    }
  }

  function resetForNew() {
    setPlaceName(""); setLocationText(""); setPickedPoint(null); setShowMap(false);
    setStory(""); setDisplayName(""); setSongTitle(""); setArtist(""); setMusicUrl("");
    setConsent(false); setPhotoFile(null); setPhotoPreview(null); setPhotoError("");
    setStatus("form"); setErrorMsg("");
  }

  if (status === "success") {
    return (
      <div className="view fade-in postcard-success">
        <div className="postcard-success-icon"><CheckCircle2 size={44} strokeWidth={1.6} /></div>
        <h1 className="page-title center">Η καρτ ποστάλ σου έφτασε!</h1>
        <p className="route-intro-text route-intro-text-center">Θα την ελέγξουμε πριν γίνει μέρος των διαδρομών μας.</p>
        <div className="route-nav route-nav-center">
          <button className="pill-btn" onClick={resetForNew}>Στείλε άλλη καρτ ποστάλ</button>
        </div>
      </div>
    );
  }

  return (
    <div className="view fade-in">
      <div className="eyebrow">POSTCARDS FROM THE ROAD 💌</div>
      <h1 className="page-title">Μια καρτ ποστάλ από τον δρόμο.</h1>
      <p className="route-intro-text">
        Κάθε τόπος κρύβει μια ιστορία. Μοιράσου μαζί μας ένα μέρος που αγαπάς, μια ανάμνηση που κουβαλάς ή μια στιγμή που θα ήθελες να ταξιδέψει λίγο πιο μακριά.
      </p>

      <label className="route-field-label">Όνομα τόπου *</label>
      <input className="route-input" placeholder="Π.χ. Η παραλία με τα κυπαρίσσια" value={placeName} onChange={(e) => setPlaceName(e.target.value)} maxLength={80} />

      <label className="route-field-label">Τοποθεσία ή προορισμός *</label>
      <input className="route-input" placeholder="Π.χ. Αντίπαξοι, Ιόνιο" value={locationText} onChange={(e) => setLocationText(e.target.value)} maxLength={120} />

      <button type="button" className="postcard-map-toggle" onClick={() => setShowMap((v) => !v)}>
        📍 {showMap ? "Κλείσε τον χάρτη" : "Βάλε το σημείο στον χάρτη (προαιρετικό)"}
      </button>
      {showMap && (
        <>
          <RouteLeafletMap selected={pickedPoint} onSelect={setPickedPoint} onFreePick={handleFreePick} />
          {pickedPoint && (
            <div className="route-confirm-line">📍 {pickedPoint.resolving ? "Εντοπίζουμε το σημείο..." : pickedPoint.name}</div>
          )}
        </>
      )}

      <label className="route-field-label">Η ιστορία σου *</label>
      <textarea className="route-textarea" placeholder="Μια ανάμνηση, μια στιγμή, μια μικρή ιστορία για αυτό το μέρος..." value={story} onChange={(e) => setStory(e.target.value)} maxLength={1000} />

      <label className="route-field-label">Φωτογραφία *</label>
      <input ref={fileInputRef} type="file" accept="image/*" className="postcard-file-input" onChange={handlePhotoChange} />
      {!photoPreview && (
        <button type="button" className="postcard-upload-btn" onClick={() => fileInputRef.current && fileInputRef.current.click()}>
          <Upload size={18} strokeWidth={1.8} /> Ανέβασε φωτογραφία
        </button>
      )}
      {photoPreview && (
        <div className="postcard-preview-wrap">
          <img src={photoPreview} alt="Προεπισκόπηση" className="postcard-preview-img" />
          <div className="postcard-preview-actions">
            <button type="button" className="pill-btn pill-btn-ghost pill-btn-sm" onClick={() => fileInputRef.current && fileInputRef.current.click()}>Αντικατάσταση</button>
            <button type="button" className="pill-btn pill-btn-ghost pill-btn-sm" onClick={removePhoto}>Αφαίρεση</button>
          </div>
        </div>
      )}
      {photoError && <div className="route-blocked-msg">{photoError}</div>}

      <div className="postcard-divider" />
      <div className="route-step-heading route-step-heading-sm">🎵 ΠΡΟΑΙΡΕΤΙΚΑ</div>
      <input className="route-input" placeholder="Τίτλος τραγουδιού" value={songTitle} onChange={(e) => setSongTitle(e.target.value)} maxLength={80} />
      <input className="route-input" placeholder="Καλλιτέχνης" value={artist} onChange={(e) => setArtist(e.target.value)} maxLength={80} />
      <input className="route-input" placeholder="Σύνδεσμος τραγουδιού" value={musicUrl} onChange={(e) => setMusicUrl(e.target.value)} maxLength={300} />
      <input className="route-input" placeholder="Το όνομά σου (προαιρετικό)" value={displayName} onChange={(e) => setDisplayName(e.target.value)} maxLength={60} />

      <label className="postcard-consent">
        <input type="checkbox" checked={consent} onChange={(e) => setConsent(e.target.checked)} />
        <span>Συμφωνώ να δημοσιευτούν η ιστορία και η φωτογραφία μου στο The Van, μετά από έλεγχο. *</span>
      </label>

      {blockedMsg && <div className="route-blocked-msg">{blockedMsg}</div>}
      {status === "error" && <div className="route-blocked-msg">{errorMsg}</div>}

      <div className="route-nav route-nav-center">
        <button className="pill-btn route-launch-btn" disabled={!canSubmit || status === "submitting"} onClick={handleSubmit}>
          {status === "submitting" ? "Στέλνεται..." : "Στείλε την καρτ ποστάλ σου"}
        </button>
      </div>
    </div>
  );
}

// ---- VAN ATLAS 🗺️ (brief section 7) ----
function AtlasEntryCard({ entry, myVanSongs, myVanPostcards, onSaveSong, onSavePostcard }) {
  const hasSong = !!(entry.songTitle || entry.artist);
  if (entry.kind === "route") {
    const songId = `route-${entry.id}`;
    const saved = myVanSongs.some((s) => s.id === songId);
    return (
      <div className="atlas-entry-card">
        <div className="atlas-entry-kind">🚐 Pick the Route</div>
        {entry.genre && <div className="atlas-entry-tag">{entry.genre}</div>}
        {hasSong && <div className="atlas-entry-song">🎵 {entry.songTitle}{entry.artist ? ` — ${entry.artist}` : ""}</div>}
        {entry.story && <div className="atlas-entry-story">{entry.story}</div>}
        <div className="atlas-entry-actions">
          {entry.musicUrl && <a className="atlas-entry-link" href={entry.musicUrl} target="_blank" rel="noreferrer">Άκου το τραγούδι ↗</a>}
          {hasSong && (
            <button
              className={`atlas-entry-save ${saved ? "atlas-entry-saved" : ""}`}
              onClick={() => onSaveSong({ id: songId, title: entry.songTitle, artist: entry.artist, musicUrl: entry.musicUrl, placeName: entry.placeName })}
            >
              {saved ? "✓ Στο My Van" : "+ My Van"}
            </button>
          )}
        </div>
      </div>
    );
  }
  const saved = myVanPostcards.some((p) => p.id === entry.id);
  return (
    <div className="atlas-entry-card">
      <div className="atlas-entry-kind">💌 Postcard</div>
      {entry.photoUrl && <img src={entry.photoUrl} alt="" className="atlas-entry-photo" />}
      {entry.story && <div className="atlas-entry-story">{entry.story}</div>}
      {hasSong && <div className="atlas-entry-song">🎵 {entry.songTitle}{entry.artist ? ` — ${entry.artist}` : ""}</div>}
      {entry.displayName && <div className="atlas-entry-byline">— {entry.displayName}</div>}
      <div className="atlas-entry-actions">
        {entry.musicUrl && <a className="atlas-entry-link" href={entry.musicUrl} target="_blank" rel="noreferrer">Άκου το τραγούδι ↗</a>}
        <button
          className={`atlas-entry-save ${saved ? "atlas-entry-saved" : ""}`}
          onClick={() => onSavePostcard({ id: entry.id, placeName: entry.placeName, story: entry.story, photoUrl: entry.photoUrl })}
        >
          {saved ? "✓ Στο My Van" : "+ My Van"}
        </button>
      </div>
    </div>
  );
}

// ---- Van Atlas clustering ----
// Real zoom-dependent clustering: the ~1km "place" groups from
// buildAtlasGroups are merged whenever they sit within ATLAS_CLUSTER_RADIUS_PX
// screen pixels of each other AT THE CURRENT ZOOM, so zooming in splits big
// circles apart and zooming out merges them. Circle size and number come from
// the real count of eligible entries (never hardcoded). Positions are
// compared in projected pixels, which depends only on zoom (not on panning),
// so clusters are recomputed on zoomend only.
const ATLAS_CLUSTER_RADIUS_PX = 52;
const ATLAS_MAX_SPLIT_ZOOM = 17;

function clusterAtlasGroups(map, groups, zoom) {
  const pts = groups
    .map((g) => { const p = map.project([g.lat, g.lon], zoom); return { g, x: p.x, y: p.y, n: g.entries.length }; })
    .sort((a, b) => b.n - a.n);
  const clusters = [];
  pts.forEach((pt) => {
    let target = null;
    let best = ATLAS_CLUSTER_RADIUS_PX;
    clusters.forEach((c) => {
      const d = Math.hypot(c.x - pt.x, c.y - pt.y);
      if (d < best) { best = d; target = c; }
    });
    if (!target) {
      clusters.push({ x: pt.x, y: pt.y, total: pt.n, groups: [pt.g] });
      return;
    }
    const t = target.total + pt.n;
    target.x = (target.x * target.total + pt.x * pt.n) / t;
    target.y = (target.y * target.total + pt.y * pt.n) / t;
    target.total = t;
    target.groups.push(pt.g);
  });
  return clusters.map((c) => {
    if (c.groups.length === 1) return { lat: c.groups[0].lat, lon: c.groups[0].lon, total: c.total, groups: c.groups };
    const ll = map.unproject([c.x, c.y], zoom);
    return { lat: ll.lat, lon: ll.lng, total: c.total, groups: c.groups };
  });
}

function makeAtlasClusterIcon(total, label, active) {
  const size = Math.round(Math.min(84, Math.max(30, 26 + Math.sqrt(total) * 6.2)));
  const tier = total >= 50 ? 3 : total >= 10 ? 2 : 1;
  const fs = size >= 64 ? 17 : size >= 44 ? 14 : 12;
  const labelHtml = label ? `<span class="atlas-cluster-label">${escapeHtml(label)}</span>` : "";
  return L.divIcon({
    className: "atlas-cluster-wrap",
    html: `<div class="atlas-cluster-holder" style="width:${size}px;height:${size}px"><div class="atlas-cluster atlas-cluster-t${tier}${active ? " atlas-cluster-active" : ""}" style="font-size:${fs}px">${total}</div>${labelHtml}</div>`,
    iconSize: [size, size],
    iconAnchor: [size / 2, size / 2],
  });
}

function AtlasClusterLayer({ groups, activeGroups, onSelect }) {
  const map = useMap();
  const [zoom, setZoom] = useState(() => map.getZoom());
  useMapEvents({ zoomend: () => setZoom(map.getZoom()) });
  const clusters = useMemo(() => clusterAtlasGroups(map, groups, zoom), [map, groups, zoom]);
  const markers = useMemo(
    () =>
      clusters.map((c) => {
        const single = c.groups.length === 1;
        const active = !!activeGroups && c.groups.some((g) => activeGroups.includes(g));
        return {
          c,
          title: single ? `${c.groups[0].name} · ${c.total}` : `${c.total} καταχωρίσεις`,
          icon: makeAtlasClusterIcon(c.total, single && zoom >= 7 ? c.groups[0].name : "", active),
        };
      }),
    [clusters, activeGroups, zoom]
  );

  function handleClick(c) {
    if (c.groups.length > 1 && zoom < ATLAS_MAX_SPLIT_ZOOM) {
      // Zoom in far enough that this cluster actually breaks apart.
      const b = L.latLngBounds(c.groups.map((g) => [g.lat, g.lon]));
      const target = Math.min(ATLAS_MAX_SPLIT_ZOOM, Math.max(zoom + 1, map.getBoundsZoom(b.pad(0.25))));
      map.setView(b.getCenter(), target, { animate: !prefersReducedMotion() });
    } else {
      onSelect(c.groups);
    }
  }

  return markers.map((m, i) => (
    <Marker key={`${zoom}-${i}`} position={[m.c.lat, m.c.lon]} icon={m.icon} title={m.title} eventHandlers={{ click: () => handleClick(m.c) }} />
  ));
}

function VanAtlasView({ myVanSongs, myVanPostcards, onSaveSong, onSavePostcard }) {
  const [status, setStatus] = useState("loading"); // loading | ready | error
  const [groups, setGroups] = useState([]);
  const [textOnly, setTextOnly] = useState([]);
  const [activeGroups, setActiveGroups] = useState(null); // array of place groups, or null
  const [panelLimit, setPanelLimit] = useState(30);
  // FIX: entries with no real coordinates (location given as text only, so
  // there's no pin to click) used to render unconditionally below the map —
  // the area under the map was never actually empty by default, it always
  // listed these. Now it stays empty until the person explicitly asks to
  // see them, same as the pin detail panel only shows after a click.
  const [showTextOnly, setShowTextOnly] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setStatus("loading");
    fetchAtlasEntries()
      .then((entries) => {
        if (cancelled) return;
        const { groups: g, textOnly: t } = buildAtlasGroups(entries);
        setGroups(g);
        setTextOnly(t);
        setActiveGroups(null);
        setShowTextOnly(false);
        setStatus("ready");
      })
      .catch((err) => {
        console.error("Van Atlas could not load:", err);
        if (!cancelled) setStatus("error");
      });
    return () => { cancelled = true; };
  }, []);

  const isEmpty = status === "ready" && groups.length === 0 && textOnly.length === 0;

  return (
    <div className="view fade-in">
      <div className="eyebrow">VAN ATLAS 🗺️</div>
      <h1 className="page-title">Οι τόποι της κοινότητας.</h1>
      <p className="route-intro-text">
        Τραγούδια, διαδρομές και ιστορίες που μοιράστηκε μαζί μας η κοινότητα — εκεί ακριβώς όπου τα τοποθέτησαν.
      </p>

      {status === "loading" && <div className="route-map-badge-standalone">Φορτώνουμε τον χάρτη της κοινότητας...</div>}
      {status === "error" && <div className="route-blocked-msg">Δεν μπορέσαμε να φορτώσουμε τον Van Atlas αυτή τη στιγμή. Δοκίμασε ξανά σε λίγο.</div>}

      {status === "ready" && (
        <>
          <div className="route-leaflet-wrap">
            <MapContainer center={[38.6, 23.4]} zoom={6} minZoom={5} scrollWheelZoom className="route-leaflet-map">
              <MapInvalidateOnMount />
              <TileLayer
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              />
              <AtlasClusterLayer groups={groups} activeGroups={activeGroups} onSelect={(gs) => { setActiveGroups(gs); setPanelLimit(30); }} />
            </MapContainer>
          </div>
          {groups.length > 0 && (
            <div className="atlas-count-note">
              {groups.reduce((n, g) => n + g.entries.length, 0)} καταχωρίσεις στον χάρτη — πάτα έναν κύκλο για να ζουμάρεις ή να δεις τι κρύβει.
            </div>
          )}

          {isEmpty && (
            <div className="empty-state">
              <div className="empty-icon-circle"><MapIcon size={30} strokeWidth={1.8} /></div>
              <div className="empty-title">Δεν υπάρχουν ακόμα καταχωρίσεις</div>
              <div className="empty-sub">Μόλις η κοινότητα διαλέξει διαδρομές ή στείλει καρτ ποστάλ, θα εμφανιστούν εδώ.</div>
            </div>
          )}

          {activeGroups && (() => {
            // Flatten (place heading + its entries) so a big merged cluster
            // can be shown progressively instead of dumping hundreds of cards.
            let shown = 0;
            const total = activeGroups.reduce((n, g) => n + g.entries.length, 0);
            return (
              <div className="atlas-detail-panel fade-in">
                <button className="atlas-detail-close" onClick={() => setActiveGroups(null)}><X size={18} /></button>
                {activeGroups.map((g, gi) => {
                  if (shown >= panelLimit) return null;
                  const room = panelLimit - shown;
                  const visible = g.entries.slice(0, room);
                  shown += visible.length;
                  return (
                    <div key={gi}>
                      <div className="atlas-detail-place">📍 {g.name}{g.entries.length > 1 ? ` · ${g.entries.length}` : ""}</div>
                      {visible.map((e, i) => (
                        <AtlasEntryCard key={e.kind + ":" + e.id + ":" + i} entry={e} myVanSongs={myVanSongs} myVanPostcards={myVanPostcards} onSaveSong={onSaveSong} onSavePostcard={onSavePostcard} />
                      ))}
                    </div>
                  );
                })}
                {total > panelLimit && (
                  <button type="button" className="postcard-map-toggle" onClick={() => setPanelLimit((n) => n + 30)}>
                    Δες περισσότερες ({total - panelLimit} ακόμα)
                  </button>
                )}
              </div>
            );
          })()}

          {!activeGroups && !showTextOnly && textOnly.length > 0 && (
            <button type="button" className="postcard-map-toggle" onClick={() => setShowTextOnly(true)}>
              📍 Δες {textOnly.length} ακόμα {textOnly.length === 1 ? "καταχώριση" : "καταχωρίσεις"} χωρίς σημείο στον χάρτη
            </button>
          )}
          {showTextOnly && textOnly.length > 0 && (
            <>
              <div className="route-step-heading route-step-heading-sm atlas-textonly-heading">
                Χωρίς σημείο στον χάρτη (η τοποθεσία δόθηκε ως κείμενο)
                <button type="button" className="atlas-textonly-hide" onClick={() => setShowTextOnly(false)}>Απόκρυψη</button>
              </div>
              {textOnly.map((e, i) => (
                <div key={i}>
                  <div className="atlas-entry-place-text">📍 {e.locationText || e.placeName}</div>
                  <AtlasEntryCard entry={e} myVanSongs={myVanSongs} myVanPostcards={myVanPostcards} onSaveSong={onSaveSong} onSavePostcard={onSavePostcard} />
                </div>
              ))}
            </>
          )}
        </>
      )}
    </div>
  );
}

