function TabBar({ tab, setTab }) {
  const tabs = [
    { key: "home", label: "Home" },
    { key: "journeys", label: "Journeys" },
    { key: "myvan", label: "My Van" },
    { key: "about", label: "About" },
  ];
  return (
    <div className="tab-bar">
      {tabs.map((t) => {
        const active = tab === t.key;
        return (
          <button key={t.key} className={`tab-btn ${active ? "tab-active" : ""}`} onClick={() => setTab(t.key)}>
            {t.key === "home" ? (
              <img src={VAN_B64} alt="" className={`tab-van-icon ${active ? "tab-van-active" : "tab-van-inactive"}`} />
            ) : t.key === "journeys" ? (
              <Radio size={21} strokeWidth={active ? 2.2 : 1.8} />
            ) : t.key === "myvan" ? (
              <Heart size={21} strokeWidth={active ? 2.2 : 1.8} fill={active ? "currentColor" : "none"} />
            ) : (
              <Info size={21} strokeWidth={active ? 2.2 : 1.8} />
            )}
            <span className="tab-label">{t.label}</span>
          </button>
        );
      })}
    </div>
  );
}

export default function TheVanApp() {
  const [tab, setTab] = useState("home");
  // My Van — Journeys favorites (UNCHANGED: same key, same array-of-ids
  // shape as before, so every already-saved favorite keeps working exactly
  // as it did). Songs and Postcards are brand-new, separate localStorage
  // keys added alongside it — nothing about the existing mechanism changes.
  const [favorites, setFavorites] = useState(() => {
    try {
      const raw = window.localStorage.getItem("tvr_my_van_favorites");
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  });
  const [myVanSongs, setMyVanSongs] = useState(() => {
    try {
      const raw = window.localStorage.getItem("tvr_my_van_songs");
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  });
  const [myVanPostcards, setMyVanPostcards] = useState(() => {
    try {
      const raw = window.localStorage.getItem("tvr_my_van_postcards");
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  });
  function handleSaveSong(song) {
    setMyVanSongs((prev) => {
      const next = prev.some((s) => s.id === song.id) ? prev.filter((s) => s.id !== song.id) : [...prev, song];
      try { window.localStorage.setItem("tvr_my_van_songs", JSON.stringify(next)); } catch (e) { /* ignore */ }
      return next;
    });
  }
  function handleSavePostcard(postcard) {
    setMyVanPostcards((prev) => {
      const next = prev.some((p) => p.id === postcard.id) ? prev.filter((p) => p.id !== postcard.id) : [...prev, postcard];
      try { window.localStorage.setItem("tvr_my_van_postcards", JSON.stringify(next)); } catch (e) { /* ignore */ }
      return next;
    });
  }
  const [currentId, setCurrentId] = useState(null);
  const [openId, setOpenId] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const audioRef = useRef(null);

  const [journeys, setJourneys] = useState(FALLBACK_JOURNEYS);
  const [journeysLoading, setJourneysLoading] = useState(true);
  const [liveOn, setLiveOn] = useState(false);
  const [copilotOpen, setCopilotOpen] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetchJourneysFromSheet()
      .then((data) => {
        if (!cancelled && data.length) setJourneys(data);
      })
      .catch((err) => {
        console.error("Could not load live episode list, using fallback:", err);
      })
      .finally(() => {
        if (!cancelled) setJourneysLoading(false);
      });
    return () => { cancelled = true; };
  }, []);

  const currentIndex = journeys.findIndex((j) => j.id === currentId);
  const currentJourney = currentIndex >= 0 ? journeys[currentIndex] : null;

  useEffect(() => {
    if (!audioRef.current) return;
    if (isPlaying) {
      const p = audioRef.current.play();
      if (p && p.catch) p.catch(() => {});
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying, currentId, liveOn]);

  function handleToggleLive() {
    if (liveOn) {
      setLiveOn(false);
      setIsPlaying(false);
    } else {
      setLiveOn(true);
      setCurrentId(null);
      setIsPlaying(true);
    }
  }

  function handlePlay(id) {
    setLiveOn(false);
    if (id === currentId) {
      setIsPlaying((p) => !p);
    } else {
      setCurrentId(id);
      setIsPlaying(true);
      setProgress(0);
    }
  }

  function handleNext() {
    if (currentIndex < 0) return;
    const nextIdx = (currentIndex + 1) % journeys.length;
    setCurrentId(journeys[nextIdx].id);
    setIsPlaying(true);
    setProgress(0);
  }

  function handlePrev() {
    if (currentIndex < 0) return;
    const prevIdx = (currentIndex - 1 + journeys.length) % journeys.length;
    setCurrentId(journeys[prevIdx].id);
    setIsPlaying(true);
    setProgress(0);
  }

  function handleFav(id) {
    setFavorites((f) => {
      const next = f.includes(id) ? f.filter((x) => x !== id) : [...f, id];
      try { window.localStorage.setItem("tvr_my_van_favorites", JSON.stringify(next)); } catch (e) { /* ignore */ }
      return next;
    });
  }

  function handleSeek(t) {
    if (audioRef.current) {
      audioRef.current.currentTime = t;
      setProgress(t);
    }
  }

  function handleClosePlayer() {
    setIsPlaying(false);
    setCurrentId(null);
    setProgress(0);
  }

  return (
    <div className="app-root">
      <style>{CSS}</style>
      <audio
        ref={audioRef}
        src={liveOn ? LIVE_STREAM_URL : (currentJourney ? currentJourney.audioUrl : undefined)}
        onTimeUpdate={(e) => !liveOn && setProgress(e.target.currentTime)}
        onLoadedMetadata={(e) => !liveOn && setDuration(e.target.duration)}
        onEnded={handleNext}
      />
      <div className="screen">
        {tab === "home" && <HomeHubView onNavigate={setTab} />}
        {tab === "journeys" && (
          <HomeView journeys={journeys} currentId={currentId} isPlaying={isPlaying} favorites={favorites} onPlay={handlePlay} onFav={handleFav} onOpen={setOpenId} />
        )}
        {tab === "myvan" && (
          <FavoritesView
            journeys={journeys}
            favorites={favorites}
            currentId={currentId}
            isPlaying={isPlaying}
            onPlay={handlePlay}
            onFav={handleFav}
            onOpen={setOpenId}
            goHome={() => setTab("journeys")}
            myVanSongs={myVanSongs}
            myVanPostcards={myVanPostcards}
            onRemoveSong={(id) => handleSaveSong({ id })}
            onRemovePostcard={(id) => handleSavePostcard({ id })}
          />
        )}
        {tab === "route" && <PickRouteView />}
        {tab === "postcards" && <PostcardsView />}
        {tab === "atlas" && (
          <VanAtlasView myVanSongs={myVanSongs} myVanPostcards={myVanPostcards} onSaveSong={handleSaveSong} onSavePostcard={handleSavePostcard} />
        )}
        {tab === "roadbook" && <RoadbookView onNavigate={setTab} />}
        {tab === "about" && <AboutView />}
      </div>
      {(tab === "home" || tab === "journeys" || tab === "myvan") && (
        <TopActionBar liveOn={liveOn} onToggleLive={handleToggleLive} onOpenCopilot={() => setCopilotOpen(true)} />
      )}
      {copilotOpen && <CoPilotChat onClose={() => setCopilotOpen(false)} />}
      {openId != null && (
        <JourneyDetail
          journey={journeys.find((j) => j.id === openId)}
          isCurrent={openId === currentId}
          isPlaying={isPlaying}
          isFav={favorites.includes(openId)}
          onPlay={handlePlay}
          onFav={handleFav}
          onClose={() => setOpenId(null)}
        />
      )}
      <MiniPlayer
        journey={liveOn ? { id: "live", title: "Moysikotherapeia — Live", date: "", imageUrl: MOYSIKO_LOGO_B64 } : currentJourney}
        isPlaying={isPlaying}
        isLive={liveOn}
        onToggle={() => setIsPlaying((p) => !p)}
        onNext={handleNext}
        onPrev={handlePrev}
        progress={progress}
        duration={duration}
        onSeek={handleSeek}
        onClose={liveOn ? handleToggleLive : handleClosePlayer}
      />
      <TabBar tab={tab} setTab={setTab} />
    </div>
  );
}

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@600;700;800&family=Inter:wght@400;500;600&family=Dancing+Script:wght@600;700&family=Playfair+Display:wght@600;700&display=swap');

:root {
  --bg: #0a0d0b;
  --surface: #121613;
  --surface-2: #1a201c;
  --border: #232b26;
  --accent: #39ACD0;
  --accent-dim: #2C86A6;
  --text: #f4f7f5;
  --text-dim: #93a39a;
  --text-dim2: #5d6a63;
}

* { box-sizing: border-box; }

.app-root {
  max-width: 460px;
  margin: 0 auto;
  min-height: 100vh;
  background: radial-gradient(120% 60% at 50% 0%, #101512 0%, var(--bg) 55%);
  color: var(--text);
  font-family: 'Inter', -apple-system, sans-serif;
  position: relative;
  padding-bottom: 158px;
  overflow-x: hidden;
}

.screen { padding: 28px 20px 12px; }

.fade-in { animation: fadeIn 0.35s ease; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }

.eyebrow {
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--accent);
  margin-bottom: 6px;
}
.eyebrow-center { text-align: center; }

.page-title {
  font-family: 'Poppins', sans-serif;
  font-size: 30px;
  font-weight: 800;
  margin: 0 0 20px;
  letter-spacing: -0.01em;
}
.page-title.center { text-align: center; margin-bottom: 6px; }

.home-logo { height: 34px; width: auto; margin-bottom: 10px; display: block; }

.section-title {
  font-family: 'Poppins', sans-serif;
  font-size: 17px;
  font-weight: 700;
  margin: 26px 0 12px;
}

/* Hero card */
.hero-card {
  position: relative;
  border-radius: 26px;
  min-height: 300px;
  background-size: cover;
  background-position: center;
  border: 1px solid var(--border);
  padding: 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 20px 40px -20px rgba(0,0,0,0.6);
}
.hero-badge {
  align-self: flex-start;
  background: rgba(57, 172, 208, 0.16);
  border: 1px solid rgba(57, 172, 208, 0.4);
  color: var(--accent);
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
  padding: 6px 12px;
  border-radius: 999px;
  backdrop-filter: blur(6px);
}
.hero-bottom {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
}
.hero-text { cursor: pointer; }
.hero-title {
  font-family: 'Poppins', sans-serif;
  font-weight: 700;
  font-size: 19px;
  line-height: 1.25;
  margin-bottom: 4px;
  text-shadow: 0 2px 10px rgba(0,0,0,0.5);
}
.hero-date { font-size: 13px; color: rgba(244,247,245,0.75); }

.play-btn-lg {
  flex-shrink: 0;
  width: 56px; height: 56px;
  border-radius: 50%;
  border: none;
  background: var(--accent);
  color: #06130a;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  box-shadow: 0 8px 24px -6px rgba(57,172,208,0.6);
  transition: transform 0.15s ease;
}
.play-btn-lg:active { transform: scale(0.92); }

/* Episode list */
.ep-list { display: flex; flex-direction: column; gap: 8px; }
.ep-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 10px;
  border-radius: 16px;
  border: 1px solid transparent;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.ep-row-active { background: rgba(57,172,208,0.08); border-color: rgba(57,172,208,0.28); }
.ep-clickable { display: flex; align-items: center; gap: 12px; flex: 1; min-width: 0; cursor: pointer; }
.ep-info { flex: 1; min-width: 0; }
.ep-title { font-size: 14.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ep-date { font-size: 12px; color: var(--text-dim); margin-top: 2px; }

.thumb-fallback {
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(145deg, var(--surface-2), var(--surface));
  color: var(--text-dim2);
  flex-shrink: 0;
}

.icon-btn {
  background: none; border: none; color: var(--text-dim);
  width: 32px; height: 32px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; flex-shrink: 0;
  transition: color 0.15s ease, background 0.15s ease;
}
.icon-btn:hover { background: var(--surface-2); color: var(--text); }
.heart-btn.heart-active { color: var(--accent); }

.play-btn-sm {
  flex-shrink: 0;
  width: 34px; height: 34px;
  border-radius: 50%;
  border: none;
  background: var(--surface-2);
  color: var(--text);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.ep-row-active .play-btn-sm { background: var(--accent); color: #06130a; }

/* Empty state */
.empty-state {
  display: flex; flex-direction: column; align-items: center; text-align: center;
  padding: 60px 20px 30px;
}
.empty-icon-circle {
  width: 68px; height: 68px; border-radius: 50%;
  background: rgba(57,172,208,0.1);
  border: 1px solid rgba(57,172,208,0.25);
  color: var(--accent);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
}
.empty-title { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 17px; margin-bottom: 8px; }
.empty-sub { font-size: 13.5px; color: var(--text-dim); max-width: 240px; line-height: 1.5; margin-bottom: 22px; }
.pill-btn {
  background: var(--accent); color: #06130a; border: none;
  font-weight: 700; font-size: 14px;
  padding: 12px 26px; border-radius: 999px; cursor: pointer;
}

/* Roadbook */
.roadbook-header {
  background: linear-gradient(160deg, #142a1c, #0d1712 70%);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 30px 20px 24px;
  display: flex; flex-direction: column; align-items: center;
  margin-bottom: 22px;
}
.roadbook-icon {
  width: 52px; height: 52px; border-radius: 50%;
  background: rgba(57,172,208,0.14);
  color: var(--accent);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 14px;
}
.roadbook-sub { font-size: 13.5px; color: var(--text-dim); text-align: center; margin-top: 2px; }
.roadbook-body {
  border-left: 2px solid var(--accent);
  padding-left: 16px;
  display: flex; flex-direction: column; gap: 16px;
}
.roadbook-p { font-size: 14.5px; line-height: 1.7; color: rgba(244,247,245,0.88); margin: 0; }
.roadbook-signature {
  font-family: 'Dancing Script', cursive;
  font-weight: 700;
  font-size: 34px;
  letter-spacing: 0.04em;
  color: var(--accent);
  text-align: right;
  margin-top: 18px;
  padding-right: 8px;
  transform: rotate(-3deg);
}

/* About */
.about-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 28px 20px 22px;
  display: flex; flex-direction: column; align-items: center;
  text-align: center;
  margin-bottom: 24px;
}
.about-logo {
  width: 84px; height: 84px; border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--accent);
  margin-bottom: 16px;
  box-shadow: 0 8px 24px -8px rgba(57,172,208,0.5);
}
.about-text { font-size: 14px; line-height: 1.7; color: rgba(244,247,245,0.85); max-width: 340px; }

.connect-list { display: flex; flex-direction: column; gap: 8px; }
.connect-row {
  display: flex; align-items: center; gap: 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 13px 14px;
  text-decoration: none;
  color: var(--text);
  transition: background 0.15s ease;
}
.connect-row:hover { background: var(--surface-2); }
.connect-icon {
  width: 34px; height: 34px; border-radius: 50%;
  background: rgba(57,172,208,0.12); color: var(--accent);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.connect-text { flex: 1; display: flex; flex-direction: column; }
.connect-label { font-size: 14px; font-weight: 600; }
.connect-sub { font-size: 12px; color: var(--text-dim); margin-top: 1px; }
.connect-chevron { color: var(--text-dim2); }

/* Mini player */
.mini-player {
  position: fixed;
  bottom: 74px;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 460px;
  background: rgba(18,22,19,0.92);
  backdrop-filter: blur(14px);
  border-top: 1px solid var(--border);
  padding: 10px 14px 8px;
  z-index: 20;
}
.mini-seek {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(to right, var(--accent) var(--pct), var(--surface-2) var(--pct));
  outline: none;
  margin-bottom: 10px;
  cursor: pointer;
}
.mini-seek::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 11px; height: 11px; border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
}
.mini-seek::-moz-range-thumb {
  width: 11px; height: 11px; border-radius: 50%;
  background: var(--accent); border: none; cursor: pointer;
}
.mini-row { display: flex; align-items: center; gap: 10px; }
.mini-info { flex: 1; min-width: 0; }
.mini-title { font-size: 13.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mini-date { font-size: 11px; color: var(--text-dim); margin-top: 1px; }
.play-btn-mini { background: var(--accent); color: #06130a; }
.mini-close { width: 30px; height: 30px; flex-shrink: 0; }

/* Tab bar */
.tab-bar {
  position: fixed;
  bottom: 0; left: 50%; transform: translateX(-50%);
  width: 100%; max-width: 460px;
  background: rgba(10,13,11,0.96);
  backdrop-filter: blur(14px);
  border-top: 1px solid var(--border);
  display: flex;
  padding: 10px 6px calc(10px + env(safe-area-inset-bottom));
  z-index: 21;
}
.tab-btn {
  flex: 1;
  background: none; border: none;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  color: var(--text-dim2);
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  padding: 4px 0;
  transition: color 0.15s ease;
}
.tab-btn.tab-active { color: var(--accent); }
.tab-label { font-size: 10.5px; font-weight: 600; }
.tab-van-icon {
  width: 22px; height: 22px; border-radius: 7px;
  object-fit: cover;
  transition: filter 0.2s ease, opacity 0.2s ease, box-shadow 0.2s ease;
}
.tab-van-inactive { filter: grayscale(1) brightness(0.75); opacity: 0.75; }
.tab-van-active { filter: none; opacity: 1; box-shadow: 0 0 0 2px var(--accent); }

/* Journey detail overlay */
.detail-overlay {
  position: fixed;
  inset: 0;
  max-width: 460px;
  margin: 0 auto;
  background: var(--bg);
  z-index: 40;
  overflow-y: auto;
}
.detail-hero-full {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.detail-hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  filter: blur(35px) brightness(0.55) saturate(1.1);
  transform: scale(1.2);
}
.detail-hero-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.detail-hero-fade {
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(10,13,11,0.05) 0%, rgba(10,13,11,0.1) 40%, rgba(10,13,11,0.72) 72%, rgba(10,13,11,0.97) 100%);
}
.detail-close {
  position: absolute;
  top: 18px; left: 18px;
  width: 38px; height: 38px;
  border-radius: 50%;
  background: rgba(10,13,11,0.55);
  backdrop-filter: blur(6px);
  border: 1px solid rgba(255,255,255,0.12);
  color: var(--text);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  z-index: 2;
}
.detail-body-bottom {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  padding: 24px 22px 40px;
  max-height: 60%;
  display: flex;
  flex-direction: column;
}
.detail-top {
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: 14px; margin-bottom: 16px;
  flex-shrink: 0;
}
.detail-title { font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 22px; line-height: 1.25; }
.detail-date { font-size: 13px; color: var(--text-dim); margin-top: 5px; }
.detail-actions { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.detail-heart {
  width: 44px; height: 44px;
  border: 1px solid var(--border);
  background: var(--surface);
}
.detail-description {
  font-size: 14.5px; line-height: 1.75; color: rgba(244,247,245,0.88); white-space: pre-line;
  overflow-y: auto;
  padding-right: 2px;
}

/* Top action bar (Live / Co-pilot) */
.top-action-bar {
  position: absolute;
  top: 30px; right: 20px;
  display: flex;
  align-items: center;
  gap: 8px;
  z-index: 15;
}
.top-action-btn {
  display: flex; align-items: center; gap: 6px;
  padding: 8px 14px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 700;
  font-family: 'Inter', sans-serif;
  border: 1px solid rgba(57,172,208,0.5);
  background: rgba(10,13,11,0.55);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: var(--text);
  cursor: pointer;
  white-space: nowrap;
}
.copilot-btn:hover { background: var(--surface-2); }
.live-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--text-dim2);
  display: inline-block;
}
.live-btn-active { background: #b3262f; border-color: #b3262f; color: #fff; }
.live-btn-active .live-dot { background: #fff; animation: pulseDot 1.4s ease-in-out infinite; }
@keyframes pulseDot { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }

/* Co-pilot chat (embedded external page) */
.copilot-frame-overlay {
  position: fixed; inset: 0; max-width: 460px; margin: 0 auto;
  background: var(--bg); z-index: 50;
  display: flex; flex-direction: column;
  height: 100vh; height: 100dvh;
}
.copilot-frame-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: calc(12px + env(safe-area-inset-top)) 16px 12px;
  border-bottom: 1px solid var(--border); background: var(--surface); flex-shrink: 0;
}
.copilot-frame-actions { display: flex; align-items: center; gap: 12px; }
.copilot-frame-link { font-size: 12px; font-weight: 600; color: var(--accent); text-decoration: none; }
.copilot-frame { flex: 1; width: 100%; min-height: 0; border: 0; background: var(--bg); }
.copilot-frame-loading { position: absolute; top: 60px; left: 0; right: 0; text-align: center; color: var(--text-dim); font-size: 13px; padding: 24px; pointer-events: none; }

/* Co-pilot chat */
.chat-overlay {
  position: fixed;
  inset: 0;
  max-width: 460px;
  margin: 0 auto;
  background: rgba(10,13,11,0.7);
  backdrop-filter: blur(4px);
  z-index: 50;
  display: flex;
  align-items: flex-end;
}
.chat-join-card {
  position: relative;
  width: 100%;
  background: var(--surface);
  border-top: 1px solid var(--border);
  border-radius: 26px 26px 0 0;
  padding: 32px 24px 40px;
  text-align: center;
}
.chat-close { position: absolute; top: 16px; right: 16px; left: auto; }
.chat-name-input {
  width: 100%;
  margin: 18px 0 16px;
  padding: 14px 16px;
  border-radius: 14px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 15px;
  font-family: 'Inter', sans-serif;
}
.chat-panel {
  width: 100%;
  height: 78vh;
  background: var(--surface);
  border-top: 1px solid var(--border);
  border-radius: 26px 26px 0 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chat-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 18px 14px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
.chat-header-title { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 16px; }
.chat-messages {
  flex: 1;
  overflow-y: auto;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.chat-msg { max-width: 78%; align-self: flex-start; }
.chat-msg-mine { align-self: flex-end; }
.chat-msg-name { font-size: 11px; color: var(--text-dim); margin-bottom: 3px; }
.chat-msg-text {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 9px 13px;
  font-size: 14px;
  line-height: 1.5;
  word-break: break-word;
}
.chat-msg-mine .chat-msg-text { background: var(--accent-dim); border-color: var(--accent); color: #fff; }
.chat-msg-gif { max-width: 180px; border-radius: 14px; display: block; }
.chat-error { padding: 24px 18px; color: var(--text-dim); font-size: 14px; text-align: center; }
.chat-emoji-row {
  display: flex; gap: 6px; padding: 8px 14px;
  border-top: 1px solid var(--border);
  overflow-x: auto;
  flex-shrink: 0;
}
.chat-emoji-btn {
  font-size: 20px; background: none; border: none; cursor: pointer;
  flex-shrink: 0;
}
.chat-input-row {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 14px;
  border-top: 1px solid var(--border);
  flex-shrink: 0;
}
.chat-text-input {
  flex: 1;
  padding: 11px 14px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 14px;
  font-family: 'Inter', sans-serif;
}
.chat-send-btn {
  padding: 10px 18px;
  border-radius: 999px;
  border: none;
  background: var(--accent);
  color: #05201f;
  font-weight: 700;
  font-size: 13.5px;
  cursor: pointer;
}

/* Pick the Route 🚐 */
.route-intro { text-align: center; padding-top: 18px; }
.route-intro-text { font-size: 14.5px; line-height: 1.7; color: var(--text-dim); margin: 14px 0 24px; }
.route-intro-text-center { text-align: center; }
.pill-btn-ghost {
  background: none; color: var(--text-dim); border: 1px solid var(--border);
  font-weight: 700; font-size: 14px;
  padding: 12px 22px; border-radius: 999px; cursor: pointer;
}
.pill-btn:disabled { opacity: 0.4; cursor: not-allowed; }
.route-stepper {
  display: flex; align-items: center; flex-wrap: wrap; gap: 4px;
  font-size: 10.5px; font-weight: 700; letter-spacing: 0.03em;
  color: var(--text-dim2); margin-bottom: 18px;
}
.route-step-active { color: var(--accent); }
.route-step-done { color: var(--text-dim); }
.route-step-arrow { color: var(--text-dim2); }
.route-step-heading {
  font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 19px;
  margin-bottom: 14px;
}
.route-step-heading-sm { font-size: 15px; margin-top: 18px; }
.route-step-heading-center { text-align: center; }

.route-board {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 5;
  border-radius: 22px;
  background: radial-gradient(120% 100% at 30% 10%, #16261d 0%, #0d1712 70%);
  border: 1px solid var(--border);
  overflow: hidden;
  margin-bottom: 16px;
}
.route-board-dots {
  position: absolute; inset: 0;
  background-image: radial-gradient(rgba(147,163,154,0.16) 1px, transparent 1px);
  background-size: 18px 18px;
}
.route-board-line { position: absolute; inset: 0; width: 100%; height: 100%; }
.route-board-line line { stroke: var(--accent); stroke-width: 0.4; opacity: 0.6; }
.route-pin {
  position: absolute;
  transform: translate(-50%, -100%);
  display: flex; flex-direction: column; align-items: center;
  gap: 3px;
  background: none; border: none; cursor: pointer; padding: 0;
  color: var(--text-dim);
}
.route-pin-choice { color: var(--text-dim); }
.route-pin-choice:hover { color: var(--text); }
.route-pin-active { color: var(--accent); }
.route-pin-dot {
  width: 9px; height: 9px; border-radius: 50%;
  background: var(--text-dim2); border: 2px solid var(--bg);
}
.route-pin-origin { color: var(--text-dim2); }
.route-pin-label {
  font-size: 9.5px; font-weight: 700; white-space: nowrap;
  background: rgba(10,13,11,0.7); padding: 2px 6px; border-radius: 6px;
}
.route-van {
  position: absolute;
  transform: translate(-50%, -50%);
  font-size: 22px;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,0.5));
}
.route-confirm-line {
  text-align: center; font-size: 14px; font-weight: 700; margin-bottom: 16px;
}
.route-board-clickable { cursor: crosshair; }
.route-pin-custom { color: var(--accent); }
.route-confirm-line span { display: block; font-size: 12.5px; font-weight: 400; color: var(--text-dim); margin-top: 3px; }
.route-nav { display: flex; gap: 10px; margin-top: 6px; }
.route-nav-center { justify-content: center; }
.route-nav .pill-btn, .route-nav .pill-btn-ghost { flex: 1; text-align: center; }
.route-nav-center .pill-btn, .route-nav-center .pill-btn-ghost { flex: none; }

.route-genre-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 8px;
}
.route-genre-card {
  background: var(--surface); border: 1px solid var(--border); color: var(--text);
  border-radius: 16px; padding: 16px 10px; font-size: 14px; font-weight: 700;
  cursor: pointer; text-align: center;
}
.route-genre-active { border-color: var(--accent); color: var(--accent); background: rgba(57,172,208,0.1); }

.route-input {
  width: 100%; padding: 13px 15px; margin-bottom: 10px;
  border-radius: 14px; border: 1px solid var(--border);
  background: var(--surface-2); color: var(--text);
  font-size: 14.5px; font-family: 'Inter', sans-serif;
}
.route-textarea {
  width: 100%; min-height: 90px; padding: 13px 15px; margin-top: 10px;
  border-radius: 14px; border: 1px solid var(--border);
  background: var(--surface-2); color: var(--text);
  font-size: 14px; font-family: 'Inter', sans-serif; line-height: 1.6;
  resize: vertical;
}
.route-preview-card {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: 16px; padding: 16px 18px; margin-bottom: 16px;
  font-size: 14px; line-height: 1.9;
}
.route-blocked-msg {
  text-align: center; font-size: 13px; color: var(--accent);
  margin-bottom: 12px;
}
.route-launch-btn { font-size: 15px; padding: 14px 28px; }
.route-driving, .route-arrived { text-align: center; padding-top: 8px; }
.route-arrived-dest { font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 24px; margin-bottom: 14px; }
.route-arrived-song { font-size: 14.5px; line-height: 1.8; margin-bottom: 18px; }
.route-arrived-note { font-weight: 700; font-size: 13px; color: var(--accent); margin-bottom: 6px; }

.route-leaflet-wrap {
  position: relative;
  width: 100%;
  height: 340px;
  border-radius: 22px;
  overflow: hidden;
  border: 1px solid var(--border);
  margin-bottom: 16px;
}
.route-leaflet-map { width: 100%; height: 100%; background: #0d1712; }
.route-leaflet-pin-inner {
  display: flex; align-items: center; gap: 5px;
  transform: translate(-4px, -22px);
  white-space: nowrap;
}
.route-leaflet-pin-dot {
  width: 12px; height: 12px; border-radius: 50%;
  background: var(--text-dim2); border: 2px solid #fff;
  box-shadow: 0 1px 4px rgba(0,0,0,0.5);
  display: inline-block; flex-shrink: 0;
}
.route-leaflet-pin-active .route-leaflet-pin-dot { background: var(--accent); }
.route-leaflet-pin-label {
  font-size: 10.5px; font-weight: 700; color: var(--text);
  background: rgba(10,13,11,0.82); padding: 2px 7px; border-radius: 6px;
}
.route-leaflet-pin-active .route-leaflet-pin-label { color: var(--accent); }
.leaflet-control-attribution { font-size: 9px !important; }
/* Official branded van marker (photo cutout) — see headingIsEastward() for
   why this mirrors instead of rotating. NOTE: the Leaflet stylesheet sets
   width:auto on .leaflet-container .leaflet-marker-pane img, which beats a
   plain class selector - that is why the marker size is ALSO set inline in
   makeVanIcon/makeFerryIcon. */
.route-leaflet-van-img {
  display: block; width: 32px; max-width: none; height: auto;
  filter: drop-shadow(0 1px 3px rgba(0,0,0,0.6));
  transform: translate(-50%, -58%);
}
.route-leaflet-van-img-flip { transform: translate(-50%, -58%) scaleX(-1); }
/* Ferry marker: small inline SVG hull with the branded van riding on top of
   it, so the van stays visible during the sea leg. */
.route-leaflet-ferry {
  position: relative; width: 64px; height: 52px;
  filter: drop-shadow(0 1px 3px rgba(0,0,0,0.55));
  transform: translate(-50%, -62%);
}
.route-leaflet-ferry-flip { transform: translate(-50%, -62%) scaleX(-1); }
.route-leaflet-ferry-van {
  position: absolute; left: 38%; top: 60%; width: 20px; max-width: none; height: auto;
  transform: translate(-50%, -50%);
}
.route-ferry-message {
  text-align: center; padding: 34px 12px; font-size: 16px; font-weight: 700;
}
.route-ferry-note {
  text-align: center; font-size: 12px; color: var(--text-dim2);
  margin-top: -6px; margin-bottom: 14px;
}

/* Home — hero photo + cards (official layout). The hero is full-bleed:
   negative margins cancel the .screen side padding and its top padding. */
.home-hub { padding-top: 0; }
.hub-hero { margin: -28px -20px 18px; }
.hub-hero-photo { position: relative; width: 100%; aspect-ratio: 1 / 0.8; overflow: hidden; }
.hub-hero-img {
  position: absolute; inset: 0; width: 100%; height: 100%;
  object-fit: cover; object-position: 62% 76%; display: block;
}
.hub-hero-scrim {
  position: absolute; inset: 0;
  background:
    linear-gradient(to top, var(--bg) 0%, rgba(10,13,11,0.82) 22%, rgba(10,13,11,0) 58%),
    linear-gradient(to bottom, rgba(10,13,11,0.55) 0%, rgba(10,13,11,0) 26%);
}
.hub-hero-logo {
  position: absolute; top: 24px; left: 20px; width: 31%; max-width: 128px; height: auto;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,0.6));
}
.hub-hero-title {
  position: absolute; left: 20px; right: 14%; bottom: 8px; margin: 0;
  font-family: 'Playfair Display', Georgia, serif; font-weight: 600;
  font-size: clamp(22px, 6.4vw, 29px); line-height: 1.16; color: #f6efe3;
  text-shadow: 0 2px 14px rgba(0,0,0,0.7);
}
.hub-hero-sub {
  margin: 4px 20px 0; font-size: 14.5px; line-height: 1.55; color: #7fb4c8; max-width: 330px;
}
.hub-card {
  position: relative; overflow: hidden; display: block; width: 100%; text-align: left;
  background-color: #08171f;
  border: 1px solid rgba(46,208,242,0.38);
  border-radius: 18px; padding: 18px 18px 16px; margin-bottom: 12px;
  cursor: pointer; color: var(--text);
}
.hub-card:active { transform: scale(0.99); }
.hub-card-icon { color: var(--accent); margin-bottom: 8px; display: flex; position: relative; }
.hub-card-icon-sm svg { width: 38px; height: 38px; }
.hub-card-roadbook { min-height: 84px; }
.hub-card-title { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 16px; margin-bottom: 5px; color: var(--accent); position: relative; }
.hub-card-title-lg { font-size: 21px; }
.hub-card-text { font-size: 13px; color: var(--text-dim); line-height: 1.55; position: relative; max-width: 62%; }
.hub-card-text-sm { max-width: none; font-size: 12px; }
.hub-card-arrow { position: absolute; right: 16px; bottom: 14px; color: var(--accent); }
.hub-card-atlas { min-height: 150px; }
.hub-card-atlas .hub-card-text { max-width: 58%; }
.hub-atlas-fade { position: absolute; inset: 0; background: linear-gradient(90deg, #08171f 0%, #08171f 24%, rgba(8,23,31,0) 54%); pointer-events: none; }
.hub-card-icon img { display: block; filter: drop-shadow(0 0 6px rgba(46,208,242,0.35)); }
.hub-card-roadbook .hub-card-wide-body { position: relative; }
.hub-card-row { display: flex; gap: 10px; margin-bottom: 0; }
.hub-card-row .hub-card-half { flex: 1 1 0; min-width: 0; padding-bottom: 40px; }
.hub-card-half .hub-card-title { font-size: 15px; }
.hub-card-half .hub-card-text { max-width: none; font-size: 12px; }
.hub-card-wide { display: flex; align-items: center; gap: 10px; padding: 14px 16px; }
.hub-card-wide .hub-card-icon { margin: 0; }
.hub-card-wide-body { flex: 1; min-width: 0; }
.hub-card-wide .hub-card-title { font-size: 14px; margin-bottom: 2px; }
.hub-card-wide .hub-card-arrow { position: static; flex-shrink: 0; }
.hub-wave { width: 54px; height: 24px; flex-shrink: 0; opacity: 0.4; }
@media (max-width: 400px) { .hub-wave { display: none; } }

.route-map-badge {
  position: absolute; left: 12px; bottom: 12px; z-index: 5;
  background: rgba(10,13,11,0.82); border: 1px solid var(--border);
  color: var(--text-dim); font-size: 11px; font-weight: 600;
  padding: 6px 11px; border-radius: 10px; max-width: calc(100% - 24px);
}

.route-field-label {
  display: block; font-size: 12px; font-weight: 700; color: var(--text-dim);
  margin: 14px 0 6px; letter-spacing: 0.02em;
}
.postcard-map-toggle {
  display: block; width: 100%; text-align: left; background: none; border: none;
  color: var(--accent); font-size: 13px; font-weight: 600; padding: 4px 0 10px; cursor: pointer;
}
.postcard-file-input { position: absolute; width: 1px; height: 1px; opacity: 0; overflow: hidden; }
.postcard-upload-btn {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  width: 100%; padding: 16px; border-radius: 16px; border: 1.5px dashed var(--border);
  background: var(--surface); color: var(--text-dim); font-size: 14px; font-weight: 600; cursor: pointer;
}
.postcard-preview-wrap { margin-bottom: 4px; }
.postcard-preview-img {
  width: 100%; max-height: 260px; object-fit: cover; border-radius: 16px;
  border: 1px solid var(--border); margin-bottom: 8px;
}
.postcard-preview-actions { display: flex; gap: 8px; }
.pill-btn-sm { font-size: 12px; padding: 7px 14px; }
.postcard-divider { height: 1px; background: var(--border); margin: 18px 0 4px; }
.postcard-consent {
  display: flex; align-items: flex-start; gap: 10px; margin: 16px 0 6px;
  font-size: 12.5px; line-height: 1.6; color: var(--text-dim); cursor: pointer;
}
.postcard-consent input { margin-top: 2px; width: 17px; height: 17px; flex-shrink: 0; accent-color: var(--accent); }
.postcard-success { text-align: center; padding-top: 24px; }
.postcard-success-icon { color: var(--accent); margin-bottom: 10px; display: flex; justify-content: center; }

.myvan-tabs { display: flex; gap: 6px; margin-bottom: 16px; }
.myvan-tab {
  flex: 1; padding: 9px 0; border-radius: 12px; border: 1px solid var(--border);
  background: var(--surface); color: var(--text-dim); font-size: 12.5px; font-weight: 700; cursor: pointer;
}
.myvan-tab-active { background: var(--accent); color: #0a0d0b; border-color: var(--accent); }
.myvan-song-list { display: flex; flex-direction: column; gap: 8px; }
.myvan-song-row {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  background: var(--surface); border: 1px solid var(--border); border-radius: 14px; padding: 12px 14px;
}
.myvan-song-title { font-weight: 700; font-size: 13.5px; }
.myvan-song-sub { font-size: 12px; color: var(--text-dim2); margin-top: 2px; }
.myvan-song-actions { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.myvan-song-link { color: var(--accent); font-size: 15px; text-decoration: none; }
.myvan-song-remove {
  background: none; border: none; color: var(--text-dim2); cursor: pointer;
  display: flex; align-items: center; padding: 2px;
}
.myvan-postcard-grid { display: flex; flex-direction: column; gap: 14px; }
.myvan-postcard-card {
  position: relative; background: var(--surface); border: 1px solid var(--border);
  border-radius: 16px; padding: 14px; padding-right: 36px;
}
.myvan-postcard-photo { width: 100%; max-height: 180px; object-fit: cover; border-radius: 12px; margin-bottom: 8px; }
.myvan-postcard-place { font-weight: 700; font-size: 13.5px; margin-bottom: 4px; }
.myvan-postcard-story { font-size: 12.5px; color: var(--text-dim); line-height: 1.6; }
.myvan-postcard-remove { position: absolute; top: 12px; right: 12px; }

.route-map-badge-standalone {
  text-align: center; font-size: 13px; color: var(--text-dim); padding: 30px 12px;
}
.atlas-cluster-wrap { background: none; border: none; }
.atlas-cluster-holder { position: relative; }
.atlas-cluster {
  width: 100%; height: 100%; box-sizing: border-box; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-family: 'Poppins', sans-serif; font-weight: 700; color: #0a0d0b;
  border: 2px solid #fff; box-shadow: 0 0 0 5px rgba(255,255,255,0.16), 0 2px 8px rgba(0,0,0,0.55);
  cursor: pointer;
}
.atlas-cluster-t1 { background: var(--accent); }
.atlas-cluster-t2 { background: #FFB020; }
.atlas-cluster-t3 { background: #E8613C; color: #fff; }
.atlas-cluster-active { box-shadow: 0 0 0 7px rgba(255,255,255,0.4), 0 2px 10px rgba(0,0,0,0.6); }
.atlas-cluster-label {
  position: absolute; top: 100%; left: 50%; transform: translateX(-50%); margin-top: 7px;
  font-size: 10px; font-weight: 700; color: var(--text); white-space: nowrap;
  background: rgba(10,13,11,0.82); padding: 1px 6px; border-radius: 6px; pointer-events: none;
}
.atlas-count-note { font-size: 12px; color: var(--text-dim); margin: 8px 2px 14px; }
.atlas-entry-kind { font-size: 10.5px; font-weight: 700; color: var(--text-dim2); margin-bottom: 4px; }
.atlas-detail-panel {
  position: relative; background: var(--surface); border: 1px solid var(--border);
  border-radius: 18px; padding: 16px 16px 10px; margin-bottom: 14px;
}
.atlas-detail-close {
  position: absolute; top: 12px; right: 12px; background: none; border: none;
  color: var(--text-dim2); cursor: pointer; display: flex;
}
.atlas-detail-place { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 15px; margin-bottom: 10px; padding-right: 26px; }
.atlas-entry-place-text { font-weight: 700; font-size: 13px; margin: 14px 0 6px; }
.atlas-entry-card {
  border-top: 1px solid var(--border); padding: 12px 0; font-size: 13px; line-height: 1.6;
}
.atlas-entry-card:first-of-type { border-top: none; padding-top: 4px; }
.atlas-entry-tag {
  display: inline-block; font-size: 10.5px; font-weight: 700; color: var(--accent);
  background: rgba(57,172,208,0.12); padding: 3px 9px; border-radius: 8px; margin-bottom: 6px;
}
.atlas-entry-song { font-weight: 700; margin-bottom: 4px; }
.atlas-entry-story { color: var(--text-dim); margin-bottom: 6px; }
.atlas-entry-byline { color: var(--text-dim2); font-size: 12px; margin-bottom: 6px; }
.atlas-entry-photo { width: 100%; max-height: 220px; object-fit: cover; border-radius: 14px; margin-bottom: 8px; }
.atlas-entry-actions { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.atlas-entry-link { color: var(--accent); font-size: 12.5px; font-weight: 600; text-decoration: none; }
.atlas-entry-save {
  background: none; border: 1px solid var(--border); color: var(--text-dim);
  font-size: 11.5px; font-weight: 700; padding: 6px 12px; border-radius: 10px; cursor: pointer;
}
.atlas-entry-saved { color: var(--accent); border-color: var(--accent); }
.atlas-textonly-heading { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.atlas-textonly-hide {
  background: none; border: none; color: var(--accent);
  font-size: 12px; font-weight: 700; cursor: pointer; padding: 0;
}

/* Roadbook — swipeable carousel */
.roadbook-cinematic { padding-bottom: 8px; }
.roadbook-carousel { position: relative; margin: 0 0 10px; }
.roadbook-track {
  display: flex; width: 100%;
  height: clamp(480px, 80vh, 620px);
  overflow-x: auto; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch;
  border-radius: 24px;
  scrollbar-width: none;
}
.roadbook-track::-webkit-scrollbar { display: none; }
.roadbook-track-slide { flex: 0 0 100%; width: 100%; height: 100%; scroll-snap-align: center; }
.roadbook-slide {
  display: flex; flex-direction: column; width: 100%; height: 100%;
  overflow: hidden; border-radius: 24px;
  background: var(--surface); border: 1px solid var(--border);
}
/* Fixed aspect ratio chosen to match the collage photos' own landscape crop
   (roughly 2.2:1 once their baked-in text is cropped off) so object-fit:
   cover only trims the edges a little instead of zooming in hard to fill a
   mismatched (much taller) box. */
.roadbook-slide-photo { width: 100%; aspect-ratio: 2.2 / 1; flex-shrink: 0; overflow: hidden; }
.roadbook-slide-photo-img { display: block; width: 100%; height: 100%; object-fit: cover; }
.roadbook-slide-content {
  flex: 1; min-height: 0; overflow-y: auto;
  padding: 18px 20px 20px;
  display: flex; flex-direction: column;
}
.roadbook-section-number {
  font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 12px;
  letter-spacing: 0.12em; color: var(--text-dim2);
}
.roadbook-section-title { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 19px; margin: 6px 0 10px; }
.roadbook-section-p { font-size: 14px; line-height: 1.7; color: rgba(244,247,245,0.86); margin: 0 0 10px; }
.roadbook-section-links { display: flex; flex-direction: column; gap: 8px; margin-top: auto; }
.roadbook-link-btn {
  text-align: left; background: var(--surface); border: 1px solid var(--border);
  color: var(--text); font-size: 13px; font-weight: 600; padding: 10px 14px;
  border-radius: 12px; cursor: pointer;
}
.roadbook-cta-row { display: flex; flex-direction: column; gap: 10px; margin-top: auto; }
.roadbook-arrow {
  position: absolute; top: 15%; transform: translateY(-50%); z-index: 5;
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(10,13,11,0.55); border: 1px solid rgba(255,255,255,0.25);
  color: #fff; display: flex; align-items: center; justify-content: center;
  cursor: pointer; backdrop-filter: blur(4px);
}
.roadbook-arrow-prev { left: 10px; }
.roadbook-arrow-next { right: 10px; }
.roadbook-dots { display: flex; align-items: center; justify-content: center; gap: 7px; margin-top: 12px; }
.roadbook-dot {
  width: 7px; height: 7px; border-radius: 4px; padding: 0; border: none;
  background: var(--border); cursor: pointer; transition: width 0.2s ease, background 0.2s ease;
}
.roadbook-dot-active { width: 20px; background: var(--accent); }
.roadbook-choice-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,0.6); z-index: 50;
  display: flex; align-items: center; justify-content: center; padding: 24px;
}
.roadbook-choice-card {
  background: var(--surface-elevated, var(--surface)); border: 1px solid var(--border);
  border-radius: 20px; padding: 24px; width: 100%; max-width: 340px;
  display: flex; flex-direction: column; gap: 10px;
}
.roadbook-choice-title { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 16px; margin-bottom: 6px; text-align: center; }
@media (prefers-reduced-motion: reduce) {
  .roadbook-track { scroll-behavior: auto; }
}
`;
